// Channel-letter module -> pricingEngine sell-price wire — pure TS, ZERO
// imports, NO IO. (ESTIMATOR_MASTERPLAN F-23a; architecture decision in
// docs/pricing-engine.md §4: "inject the shared engine underneath the module
// estimators as the sell-price stage" — the module's cost math stays
// authoritative, the engine standardizes the sell tail.)
//
// This file is the DETECTION + RESOLUTION layer only. It never imports the
// engine; the caller injects it (`engine: { pricePart, resolveTemplatePrice?,
// templatePartDescriptor? }`) so the same file bundles for the Vite frontend
// AND Deno-style functions.
//
// ---------------------------------------------------------------------------
// ZERO-REGRESSION CONTRACT
// ---------------------------------------------------------------------------
// When a channel record/line carries NO engine config — no `pricing_engine`
// context block and no line-level tier/template/override descriptor — every
// resolver returns a PASSTHROUGH marker and `sellPrice`/`sellTotal` echo the
// input costs VERBATIM (no rounding, no re-ordering). Callers keep today's
// math byte-identically in that case. Legacy `customer_pricing` /
// `pricing_tier` / `customer_tier` record fields are the OLD MarkupTier
// system: by themselves they never count as engine config — they only feed a
// real `pricing_engine` block as the customer-tier hint.
//
// ---------------------------------------------------------------------------
// Entity contract — canonical stored spellings
// ---------------------------------------------------------------------------
//   ChannelLetterInstallation record (saved by ChannelLetterEstimator.jsx):
//     items[]               {item_total_cost, labor_cost, materials_cost,
//                            labor_hours, qty_letters, description,
//                            installation_type, materials[] (unit-cost enums —
//                            NEVER scanned for engine fields)}
//     letter_purchases[]    {total_cost, qty, unit_cost, letter_type,
//                            description, fab_config{material_cost,
//                            paint_material_cost, cnc_labor_cost,
//                            paint_labor_cost}, raceway_total, backer_total}
//     selected_equipment[]  {total_cost, equipment_name, equipment_id}
//     personnel[]           {total_cost | hourly_rate*hours, name|role}
//     labor_priced_via_personnel / labor_cost_in_subtotal
//                           (personnel rows REPLACE flat-rate item labor)
//     letters_subtotal, total_letters_cost, letters_*_fee (delivery/design/
//                            install_supplies/permitting/other — delivery is
//                            skipped when EVERY purchase is dimensional_letters)
//     total_supplies_cost, total_travel_cost, subtotal, markup_amount,
//                            markup_percent, total_cost
//
//   Engine context block (TOLERATED EXTRA — no declared field today):
//     record.pricing_engine | engine_pricing | pricing_tier_config |
//       pricing_context | customer_pricing.engine_context |
//       customer_pricing.pricing_engine  — object carrying:
//         customer_tier|customerTier|tier        tier key(s) for the chart
//         tier_rules|tierRules|rules|matrix|matrix_rows|rows|pricing_matrix
//                                                PricingTierMatrix-like rows
//         template|pricing_template              descriptor passed to
//                                                resolveTemplatePrice opts
//         templates|pricing_templates            PricingTemplate registry rows
//         tiers|markup_tiers                     MarkupTier catalog rows
//         machine|machine_override               machine descriptor
//         default_markup_pct|defaultMarkupPct|default_markup|markup_pct
//                                                shop fallback % (blank ->
//                                                record.markup_percent)
//         taxable, tax_percent|taxPercent, setup_fee|setupFee,
//         minimum_charge|minimumCharge|min_charge, modifiers|formula_modifiers
//
//   Line-level config (TOLERATED EXTRA on items[] / letter_purchases[] /
//   selected_equipment[] / personnel[] rows):
//     part descriptor objects   part|pricing|price_config|tier_config|
//                               sell_pricing  — scanned for engine override
//                               fields (same vocabulary as inline below)
//     inline override fields    tier_ref|tier|tier_name,
//                               fixed_price|price_override|override_price,
//                               per_unit_breaks|unit_breaks|qty_breaks,
//                               markup_pct|markup|markup_percent,
//                               pricing_mode|price_mode (RECOGNIZED tokens
//                               only — 'market','market_based','fixed',
//                               'cost_plus' family; unit enums like
//                               'per_letter_flat'/'per_day' are ignored),
//                               market_retail, market_discount_pct,
//                               formula_modifiers|modifiers,
//                               minimum_charge|min_charge, setup_fee,
//                               customer_tier, tier_rules|matrix,
//     template refs             pricing_template_id|template_id|
//                               margin_template_id|pricing_template_name|
//                               template_name  (+ embedded pricing_template|
//                               template|price_template record)
//     machine descriptor        machine|machine_override|machine_pricing|
//                               equipment_pricing
//
// ---------------------------------------------------------------------------
// Resolution model
// ---------------------------------------------------------------------------
//   channelEngineContext(record)  — finds + normalizes the context block.
//   channelLinePricingConfig(line)— per-line engine-config detection.
//   channelCostLines(record)      — projects the saved record into granular
//                                   cost lines mirroring
//                                   categorizeChannelLetterProject's
//                                   aggregation (per-purchase [dimensional
//                                   fab split], letter fees, per-item labor
//                                   [dropped when personnel-priced] +
//                                   materials, equipment, personnel,
//                                   supplies, travel). Sum = the record's
//                                   internalCost basis.
//   wireChannelLineSell           — one line: passthrough marker or
//                                   engine.pricePart() breakdown + chain.
//   wireChannelProjectSell        — roll-up over channelCostLines; all-
//                                   passthrough -> verbatim sum.
//   channelEngineEconomics        — the boundary helper consumed by
//                                   customerPricing.sourceProjectEconomics:
//                                   {wired:false,passthrough} or
//                                   {wired:true, internalCost (echoed),
//                                    customerPrice: engine sellTotal, sell}.
//
// Engagement rules (documented for sibling wires):
//   * `pricing_engine` context block present -> EVERY line runs through the
//     engine (per-line descriptors override where present; unconfigured lines
//     price via the context chart/default markup — the engine owns the tail).
//   * Only line-level config (no context) -> configured lines engine-priced,
//     unconfigured lines passthrough VERBATIM ("tier config changes price
//     only where assigned").
//   * Neither -> all-passthrough, byte-identical.
//   * When BOTH a legacy saved customer_pricing.total AND engine config
//     exist, the engine wins — the explicit pricing_engine block / line
//     descriptors are the newer, more specific layer (recorded in chain).
//
// ---------------------------------------------------------------------------
// Schema gaps (orchestrator notes — nothing required for the core path)
// ---------------------------------------------------------------------------
//   - pricing_engine context block + every line-level config field are
//     TOLERATED EXTRAS persisted inside the project JSON; no entity field is
//     declared for them today. Declare canonical fields when admin surfaces
//     write them.
//   - templates / tiers / tier_rules registries ride inside the context block;
//     a future loader can persist refs instead (the resolvers also accept
//     ref-only descriptors — resolution happens against supplied registries).
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const num = (v: unknown, fallback = 0): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

const normStr = (v: unknown): string => String(v ?? '').trim().toLowerCase();

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;
const round4 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 10000) / 10000;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  if (!rec) return null;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '' && Number.isFinite(Number(v))) return Number(v);
  }
  return null;
};

const firstNonBlank = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown =>
  firstField(rec, fields);

// ---------------------------------------------------------------------------
// Vocabulary
// ---------------------------------------------------------------------------

/** Module keys the channel record answers to (moduleRegistry + module names). */
export const CHANNEL_MODULE_KEYS = Object.freeze([
  'channel_letters', 'channel_letter', 'channel_letter_installation',
] as const);

/** Record-level fields probed for the engine context block (in order). */
export const CHANNEL_ENGINE_CONTEXT_FIELDS = Object.freeze([
  'pricing_engine', 'engine_pricing', 'pricing_tier_config', 'pricing_context',
] as const);

/** customer_pricing sub-fields also probed (the saved tier snapshot block). */
export const CHANNEL_NESTED_CONTEXT_FIELDS = Object.freeze([
  'engine_context', 'pricing_engine',
] as const);

/** Line-level fields that may hold an engine part/override descriptor. */
export const CHANNEL_LINE_PART_FIELDS = Object.freeze([
  'part', 'pricing', 'price_config', 'tier_config', 'sell_pricing',
] as const);

/** Line-level fields that may hold a machine descriptor. */
export const CHANNEL_LINE_MACHINE_FIELDS = Object.freeze([
  'machine', 'machine_override', 'machine_pricing', 'equipment_pricing',
] as const);

/** Line-level fields that may hold / reference a PricingTemplate. */
export const CHANNEL_LINE_TEMPLATE_FIELDS = Object.freeze([
  'pricing_template', 'price_template', 'template',
] as const);
export const CHANNEL_LINE_TEMPLATE_ID_FIELDS = Object.freeze([
  'pricing_template_id', 'template_id', 'margin_template_id',
] as const);
export const CHANNEL_LINE_TEMPLATE_NAME_FIELDS = Object.freeze([
  'pricing_template_name', 'template_name',
] as const);

/** Recognized pricing-mode tokens (mirrors pricingEngine MODE_TOKENS — kept
 * local because this file never imports). Unit enums such as 'per_letter_flat'
 * or 'per_day' are deliberately NOT here and never count as config. */
const ENGINE_MODE_TOKENS: ReadonlySet<string> = new Set([
  'fixed', 'fixed_price', 'flat',
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'cost_plus', 'cost-plus', 'costplus', 'markup', 'tier', 'tier_markup', 'tiered',
]);

/** Inline override fields scanned on a raw line/descriptor. */
const FIXED_PRICE_FIELDS = ['fixed_price', 'price_override', 'override_price'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MARKET_RETAIL_FIELDS = ['market_retail', 'retail_price', 'retail'] as const;
const TIER_REF_FIELDS = ['tier_ref'] as const;
const MODIFIER_FIELDS = ['formula_modifiers', 'modifiers'] as const;
const MIN_CHARGE_FIELDS = ['minimum_charge', 'min_charge'] as const;
const TIER_RULES_FIELDS = ['tier_rules', 'tierRules', 'rules', 'matrix', 'matrix_rows', 'rows', 'pricing_matrix'] as const;
const CUSTOMER_TIER_FIELDS = ['customer_tier', 'customerTier'] as const;
const SETUP_FEE_FIELDS = ['setup_fee', 'setupFee'] as const;
const TAX_PCT_FIELDS = ['tax_percent', 'taxPercent'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode', 'active_mode'] as const;
const TEMPLATE_REGISTRY_FIELDS = ['templates', 'pricing_templates'] as const;
const TIER_CATALOG_FIELDS = ['tiers', 'markup_tiers'] as const;
const DEFAULT_MARKUP_FIELDS = ['default_markup_pct', 'defaultMarkupPct', 'default_markup'] as const;

const nonBlank = (v: unknown): boolean => normStr(v) !== '';

const hasBreakChart = (src: any): boolean =>
  BREAK_FIELDS.some((f) => Array.isArray(src?.[f]) && src[f].length > 0);

const hasTemplateEmbed = (src: any): boolean =>
  CHANNEL_LINE_TEMPLATE_FIELDS.some((f) => isRecord(src?.[f]));

const templateRefValue = (src: any): { ref: unknown; via: string } | null => {
  for (const f of CHANNEL_LINE_TEMPLATE_ID_FIELDS) {
    if (nonBlank(src?.[f])) return { ref: src[f], via: f };
  }
  for (const f of CHANNEL_LINE_TEMPLATE_NAME_FIELDS) {
    if (nonBlank(src?.[f])) return { ref: src[f], via: f };
  }
  for (const f of CHANNEL_LINE_TEMPLATE_FIELDS) {
    const v = src?.[f];
    if (v !== undefined && v !== null && !isRecord(v) && nonBlank(v)) return { ref: v, via: f };
  }
  return null;
};

/**
 * Does one record carry ANY engine override/context signal? Shared by
 * line-level scanning and part-descriptor sub-object scanning. Mirrors
 * pricingEngine.overrideRule's own precedence of what counts as a signal:
 * fixed price (positive) > tier ref > break chart > recognized mode/market
 * fields > markup pct (nonzero) > modifiers/minimums. `tier_rules` /
 * `customer_tier` are context signals — a line carrying its own chart IS
 * tier config.
 */
function descriptorConfigured(src: any): { configured: boolean; via: string[] } {
  const via: string[] = [];
  if (!isRecord(src)) return { configured: false, via };
  const fixed = firstFinite(src, FIXED_PRICE_FIELDS);
  if (fixed !== null && fixed > 0) via.push('fixed_price');
  for (const f of TIER_REF_FIELDS) if (nonBlank(src[f])) via.push(f);
  // bare `tier`/`tier_name` count only as override tokens when they carry a
  // non-blank value — they are context fields on descriptors but a pinned
  // tier ref is config.
  for (const f of ['tier', 'tier_name'] as const) if (nonBlank(src[f])) via.push(f);
  if (hasBreakChart(src)) via.push('per_unit_breaks');
  const retail = firstFinite(src, MARKET_RETAIL_FIELDS);
  if (retail !== null && retail > 0) via.push('market_retail');
  const mode = firstField(src, MODE_FIELDS);
  if (mode !== undefined && ENGINE_MODE_TOKENS.has(normStr(mode))) via.push('pricing_mode');
  const markup = firstFinite(src, MARKUP_FIELDS);
  if (markup !== null && markup !== 0) via.push('markup_pct');
  for (const f of MODIFIER_FIELDS) {
    if (Array.isArray(src[f]) && src[f].length > 0) { via.push('formula_modifiers'); break; }
  }
  if (firstFinite(src, MIN_CHARGE_FIELDS) !== null) via.push('minimum_charge');
  if (firstFinite(src, SETUP_FEE_FIELDS) !== null) via.push('setup_fee');
  for (const f of TIER_RULES_FIELDS) {
    if (Array.isArray(src[f]) && src[f].length > 0) { via.push('tier_rules'); break; }
  }
  for (const f of CUSTOMER_TIER_FIELDS) {
    if (nonBlank(src[f])) { via.push('customer_tier'); break; }
  }
  if (templateRefValue(src) || hasTemplateEmbed(src)) via.push('pricing_template');
  return { configured: via.length > 0, via };
}

// ---------------------------------------------------------------------------
// channelEngineContext — record-level context block resolution
// ---------------------------------------------------------------------------

export interface ChannelEngineContext {
  /** Marker so callers can pass the normalized context back without a rescan. */
  __channelPricingContext: true;
  /** Which record field supplied the block ('' when synthesized). */
  field: string;
  /** Customer tier value/keys for chart matching (null when unset). */
  customerTier: unknown;
  /** PricingTierMatrix-like chart rows for resolveTier/pricePart. */
  tierRules: unknown[];
  /** Optional context-level template descriptor (record object or ref). */
  template: unknown;
  /** PricingTemplate registry rows for resolveTemplatePrice. */
  templates: unknown[];
  /** MarkupTier-like catalog rows (tier-key expansion). */
  tiers: unknown[];
  /** Context-level machine descriptor. */
  machine: unknown;
  /** Shop fallback markup pct (defaults to record.markup_percent). */
  defaultMarkupPct: number;
  /** Context-level floors/fees/tax applied to every engine-priced line. */
  taxable: boolean | undefined;
  taxPercent: number;
  setupFee: number;
  minimumCharge: number;
  modifiers: unknown[] | undefined;
  /** The raw context block (audit echo). */
  raw: unknown;
}

/**
 * Find + normalize the record's engine context block.
 * Returns null when NO context block exists — legacy customer_pricing /
 * pricing_tier / customer_tier alone never constitute an engine context
 * (zero-regression gate). When a block exists but a field is absent the
 * record's own values fill in (markup_percent -> defaultMarkupPct;
 * customer_tier/pricing_tier/customer_pricing tier -> customerTier).
 */
export function channelEngineContext(source: any): ChannelEngineContext | null {
  if (source && source.__channelPricingContext === true) return source as ChannelEngineContext;
  if (!isRecord(source)) return null;

  let block: any = null;
  let field = '';
  for (const f of CHANNEL_ENGINE_CONTEXT_FIELDS) {
    if (isRecord(source[f])) { block = source[f]; field = f; break; }
  }
  if (!block && isRecord(source.customer_pricing)) {
    for (const f of CHANNEL_NESTED_CONTEXT_FIELDS) {
      if (isRecord(source.customer_pricing[f])) {
        block = source.customer_pricing[f];
        field = `customer_pricing.${f}`;
        break;
      }
    }
  }
  if (!block) return null;

  const firstArr = (src: any, fields: readonly string[]): unknown[] => {
    for (const f of fields) if (Array.isArray(src?.[f]) && src[f].length > 0) return src[f];
    return [];
  };

  const cp = isRecord(source.customer_pricing) ? source.customer_pricing : null;
  const customerTier =
    firstNonBlank(block, [...CUSTOMER_TIER_FIELDS, 'tier']) ??
    firstNonBlank(source, [...CUSTOMER_TIER_FIELDS, 'pricing_tier']) ??
    (cp ? (cp.tier_number ?? cp.tier_name ?? undefined) : undefined) ??
    null;

  const defaultMarkup =
    firstFinite(block, DEFAULT_MARKUP_FIELDS) ??
    firstFinite(block, MARKUP_FIELDS) ??
    (Number.isFinite(Number(source.markup_percent)) ? num(source.markup_percent) : 0);

  return {
    __channelPricingContext: true,
    field,
    customerTier,
    tierRules: firstArr(block, TIER_RULES_FIELDS),
    template: firstField(block, ['template', 'pricing_template']),
    templates: firstArr(block, TEMPLATE_REGISTRY_FIELDS),
    tiers: firstArr(block, TIER_CATALOG_FIELDS),
    machine: firstField(block, ['machine', 'machine_override']),
    defaultMarkupPct: num(defaultMarkup),
    taxable: typeof block.taxable === 'boolean' ? block.taxable
      : normStr(block.taxable) === 'false' ? false
      : normStr(block.taxable) === 'true' ? true : undefined,
    taxPercent: num(firstFinite(block, TAX_PCT_FIELDS)),
    setupFee: num(firstFinite(block, SETUP_FEE_FIELDS)),
    minimumCharge: num(firstFinite(block, MIN_CHARGE_FIELDS)),
    modifiers: Array.isArray(block.modifiers) ? block.modifiers
      : Array.isArray(block.formula_modifiers) ? block.formula_modifiers : undefined,
    raw: block,
  };
}

// ---------------------------------------------------------------------------
// channelLinePricingConfig — per-line engine-config detection
// ---------------------------------------------------------------------------

export interface ChannelLineConfig {
  /** True when the line carries any engine signal (descriptor/context/ref). */
  configured: boolean;
  /** Engine `part` descriptor — line-level object merged over inline fields. */
  part: any;
  /** Engine `machine` descriptor (null when absent). */
  machine: any;
  /** Template descriptor: embedded record, scalar ref, or null. */
  template: unknown;
  /** Which signals fired (audit). */
  via: string[];
}

/**
 * Detect engine config on a channel line (raw item / letter_purchase /
 * equipment / personnel row — or an already-projected cost line whose `line`
 * ref is the raw row). Descriptor objects under part|pricing|price_config|
 * tier_config|sell_pricing are scanned first; inline override fields on the
 * line itself merge underneath them.
 *
 * Deliberately NOT config (all present on today's saved records):
 *   materials[].pricing_mode unit enums ('per_letter_flat', ...),
 *   equipment pricing_mode duration enums ('per_day', 'per_hour', 'owned_flat'),
 *   unit_cost_override / *_total_override cost-side flags,
 *   qty / unit_cost / total_cost cost fields.
 */
export function channelLinePricingConfig(line: any): ChannelLineConfig {
  const src: any = isRecord(line?.line) && !isRecord(line?.part)
    ? line.line // projected cost line: config lives on the raw row
    : line;
  const via: string[] = [];

  // 1. Descriptor objects (first non-empty one wins; all scanned for `via`).
  let part: any = null;
  for (const f of CHANNEL_LINE_PART_FIELDS) {
    const d = src?.[f];
    if (!isRecord(d)) continue;
    const probe = descriptorConfigured(d);
    via.push(...probe.via.map((v) => `${f}.${v}`));
    if (probe.configured && !part) part = { ...d, __via: f };
  }

  // 2. Inline override/context fields on the line itself.
  const inline = descriptorConfigured(src);
  if (inline.configured) {
    via.push(...inline.via);
    const merged: any = {};
    for (const f of [
      ...FIXED_PRICE_FIELDS, ...TIER_REF_FIELDS, 'tier', 'tier_name',
      ...BREAK_FIELDS, ...MARKET_RETAIL_FIELDS, 'market_discount_pct',
      ...MODE_FIELDS, ...MARKUP_FIELDS, ...MODIFIER_FIELDS,
      ...MIN_CHARGE_FIELDS, ...SETUP_FEE_FIELDS,
    ]) {
      if (src[f] !== undefined && src[f] !== null && src[f] !== '') merged[f] = src[f];
    }
    part = part ? { ...merged, ...part } : merged; // explicit part object wins on conflict
  }

  // 3. Machine descriptor.
  let machine: any = null;
  for (const f of CHANNEL_LINE_MACHINE_FIELDS) {
    if (isRecord(src?.[f])) {
      machine = src[f];
      via.push(f);
      break;
    }
  }

  // 4. Template ref/embedding.
  let template: unknown = null;
  const tref = templateRefValue(src);
  if (tref) { template = tref.ref; via.push(tref.via); }
  else {
    for (const f of CHANNEL_LINE_TEMPLATE_FIELDS) {
      if (isRecord(src?.[f])) { template = src[f]; via.push(f); break; }
    }
  }
  if (!template && isRecord(part)) {
    const ptref = templateRefValue(part);
    if (ptref) { template = ptref.ref; via.push(`part.${ptref.via}`); }
    else {
      for (const f of CHANNEL_LINE_TEMPLATE_FIELDS) {
        if (isRecord(part[f])) { template = part[f]; via.push(`part.${f}`); break; }
      }
    }
  }

  return { configured: via.length > 0, part, machine, template, via };
}

// ---------------------------------------------------------------------------
// channelCostLines — project the saved record into granular cost lines
// ---------------------------------------------------------------------------

export interface ChannelCostLine {
  /** Deterministic key ('purchase:0', 'item:2:labor', 'supplies', ...). */
  key: string;
  label: string;
  /** The module-authoritative cost for this line (verbatim from the record). */
  cost: number;
  /** Pricing-unit qty for break charts (real qty where the module has one). */
  qty: number;
  /** Unit cost base = cost/qty when qty>0, else cost. */
  unitCost: number;
  /** Markup-category key (categorizeChannelLetterProject parity). */
  category: string;
  /** Which record family produced the line. */
  family: 'letter_purchase' | 'letter_fees' | 'install_item' | 'equipment'
    | 'personnel' | 'supplies' | 'travel' | 'other';
  /** The raw record row — line-level engine config is read off this. */
  line: any;
}

const labelOr = (...vals: unknown[]): string => {
  for (const v of vals) {
    const s = String(v ?? '').trim();
    if (s) return s;
  }
  return '';
};

/**
 * Granular cost projection of a saved channel record. Mirrors
 * categorizeChannelLetterProject's aggregation rules (dimensional fab split,
 * delivery-fee exclusion when every purchase is dimensional, personnel-priced
 * labor replacing flat-rate item labor) but keeps per-row granularity so a
 * part/line carrying tier config prices on its own.
 *
 * Sum invariant: Σ cost == labor_cost_in_subtotal + total_materials_cost +
 * total_supplies_cost + total_equipment_cost + total_personnel_cost +
 * total_travel_cost + letters_subtotal  == the record's internalCost basis.
 */
export function channelCostLines(record: any): ChannelCostLine[] {
  if (!isRecord(record)) return [];
  const lines: ChannelCostLine[] = [];
  const push = (l: Omit<ChannelCostLine, 'unitCost'> & { unitCost?: number }) => {
    const cost = num(l.cost);
    const qty = num(l.qty, 0) > 0 ? num(l.qty) : 1;
    const unitCost = Number.isFinite(Number(l.unitCost))
      ? num(l.unitCost)
      : (num(l.qty, 0) > 0 ? cost / num(l.qty) : cost);
    lines.push({ ...l, cost, qty, unitCost } as ChannelCostLine);
  };

  // 1. Letter purchases — dimensional splits into material / fab labor /
  //    remainder (categorizer parity); others stay one line.
  const purchases = Array.isArray(record.letter_purchases) ? record.letter_purchases : [];
  purchases.forEach((lp: any, i: number) => {
    const total = num(lp?.total_cost, num(lp?.line_total, num(lp?.qty, 0) * num(lp?.unit_cost)));
    if (total <= 0) return;
    const desc = labelOr(lp?.description, lp?.letter_type, `Purchase ${i + 1}`);
    const qty = num(lp?.qty, 0);
    const isDimensional = lp?.letter_type === 'dimensional_letters';
    if (isDimensional && isRecord(lp?.fab_config)) {
      const matCost = num(lp.fab_config.material_cost) + num(lp.fab_config.paint_material_cost);
      const laborCost = num(lp.fab_config.cnc_labor_cost) + num(lp.fab_config.paint_labor_cost);
      if (matCost > 0) {
        push({ key: `purchase:${i}:material`, label: `Dimensional Letter Material — ${desc}`,
          cost: matCost, qty, category: 'substrates', family: 'letter_purchase', line: lp });
      }
      if (laborCost > 0) {
        push({ key: `purchase:${i}:labor`, label: `Dimensional Letter Fab Labor — ${desc}`,
          cost: laborCost, qty, category: 'inhouse_labor', family: 'letter_purchase', line: lp });
      }
      const remainder = total - matCost - laborCost;
      if (remainder > 0.01) {
        push({ key: `purchase:${i}:other`, label: `Dimensional Letter (other) — ${desc}`,
          cost: remainder, qty, category: 'substrates', family: 'letter_purchase', line: lp });
      }
    } else {
      push({
        key: `purchase:${i}`,
        label: isDimensional ? `Dimensional Letters — ${desc}` : `Letter Purchase — ${desc}`,
        cost: total, qty, category: isDimensional ? 'substrates' : 'outsourced_fab',
        family: 'letter_purchase', line: lp,
      });
    }
  });

  // 2. Letter fees — delivery excluded when EVERY purchase is dimensional
  //    (calcLettersTotals + categorizer parity).
  const onlyDimensional = purchases.length > 0 &&
    purchases.every((lp: any) => lp?.letter_type === 'dimensional_letters');
  const letterFees =
    (onlyDimensional ? 0 : num(record.letters_delivery_fee)) +
    num(record.letters_design_fee) +
    num(record.letters_install_supplies_fee) +
    num(record.letters_permitting_fee) +
    num(record.letters_other_fee);
  if (letterFees > 0) {
    // `line: null` — the raw row here would be the whole record, whose own
    // legacy fields (markup_percent, customer_pricing, customer_tier) must
    // never trip line-level detection. Project-level lines configure through
    // the pricing_engine context instead.
    push({ key: 'letter_fees', label: 'Letter Fees (delivery/design/permit/etc.)',
      cost: letterFees, qty: 1, category: 'outsourced_fab', family: 'letter_fees', line: null });
  }

  // 3. Install items — labor + materials sub-lines. When a crew is assigned,
  //    personnel pricing REPLACES flat-rate item labor (labor_cost_in_subtotal
  //    = 0) so the labor sub-line drops to keep the sum on internalCost.
  const laborViaPersonnel = record.labor_priced_via_personnel !== undefined
    ? !!record.labor_priced_via_personnel
    : num(record.total_personnel_cost) > 0;
  const items = Array.isArray(record.items) ? record.items : [];
  items.forEach((it: any, i: number) => {
    const desc = labelOr(it?.description, it?.installation_type, `Item ${i + 1}`);
    const laborCost = num(it?.labor_cost);
    const materialsCost = num(it?.materials_cost);
    if (!laborViaPersonnel && laborCost > 0) {
      push({ key: `item:${i}:labor`, label: `Install Labor — ${desc}`,
        cost: laborCost, qty: num(it?.qty_letters, 0) || 1,
        category: 'inhouse_labor', family: 'install_item', line: it });
    }
    if (materialsCost > 0) {
      push({ key: `item:${i}:materials`, label: `Install Materials — ${desc}`,
        cost: materialsCost, qty: num(it?.qty_letters, 0) || 1,
        category: 'outsourced_fab', family: 'install_item', line: it });
    }
    if (!laborViaPersonnel && laborCost <= 0 && materialsCost <= 0 && num(it?.item_total_cost) > 0) {
      // Older saved shapes without the split — take the stored total whole.
      push({ key: `item:${i}`, label: `Install Item — ${desc}`,
        cost: num(it.item_total_cost), qty: num(it?.qty_letters, 0) || 1,
        category: 'outsourced_fab', family: 'install_item', line: it });
    }
    if (laborViaPersonnel && materialsCost <= 0 && laborCost <= 0 && num(it?.item_total_cost) > 0) {
      // Personnel-priced record whose item only carries the combined total:
      // charge the materials share only (labor already lives in personnel).
      const matShare = num(it.item_total_cost) - laborCost;
      if (matShare > 0) {
        push({ key: `item:${i}`, label: `Install Materials — ${desc}`,
          cost: matShare, qty: num(it?.qty_letters, 0) || 1,
          category: 'outsourced_fab', family: 'install_item', line: it });
      }
    }
  });

  // 4. Equipment rows.
  (Array.isArray(record.selected_equipment) ? record.selected_equipment : []).forEach((sel: any, i: number) => {
    const cost = num(sel?.total_cost);
    if (cost <= 0) return;
    push({ key: `equipment:${i}`, label: `Equipment — ${labelOr(sel?.equipment_name, sel?.equipment_id, `Row ${i + 1}`)}`,
      cost, qty: 1, category: 'outsourced_services', family: 'equipment', line: sel });
  });

  // 5. Personnel rows.
  (Array.isArray(record.personnel) ? record.personnel : []).forEach((p: any, i: number) => {
    const cost = num(p?.total_cost, num(p?.hourly_rate) * num(p?.hours));
    if (cost <= 0) return;
    push({ key: `personnel:${i}`, label: `Crew — ${labelOr(p?.name, p?.role, p?.title, `Row ${i + 1}`)}`,
      cost, qty: num(p?.hours, 0) || 1, category: 'inhouse_labor', family: 'personnel', line: p });
  });

  // 6. Supplies + travel (project-level lines).
  const supplies = num(record.total_supplies_cost);
  if (supplies > 0) {
    push({ key: 'supplies', label: 'Supplies', cost: supplies, qty: 1,
      category: 'outsourced_fab', family: 'supplies', line: null });
  }
  const travel = num(record.total_travel_cost);
  if (travel > 0) {
    push({ key: 'travel', label: 'Travel & Fuel', cost: travel, qty: 1,
      category: 'outsourced_services', family: 'travel', line: null });
  }

  return lines;
}

// ---------------------------------------------------------------------------
// wireChannelLineSell — one cost line through the engine (or passthrough)
// ---------------------------------------------------------------------------

const enginePricer = (engine: any): ((input: any) => any) | null =>
  typeof engine === 'function' ? engine
  : typeof engine?.pricePart === 'function' ? engine.pricePart
  : null;

export interface ChannelSellResult {
  /** True when the engine priced this line. */
  priced: boolean;
  /** True when the line echoed its cost verbatim (no engine call). */
  passthrough: boolean;
  /** 'no_tier_config' | 'engine_unavailable' | null on priced results. */
  reason: string | null;
  /** Sell price for the line — engine total when priced, verbatim cost when not. */
  sellPrice: number;
  /** Echoed inputs. */
  key: string;
  label: string;
  cost: number;
  qty: number;
  unitCost: number;
  category: string;
  /** Engine detail (priced lines only). */
  unitPrice?: number;
  extension?: number;
  priceSource?: string;
  tierSource?: string;
  engine?: any;
  /** Config detection echo. */
  via: string[];
  /** Evaluation chain — every step taken, in order. */
  chain: Array<{ step: string; detail: string }>;
}

/**
 * Price one channel cost line through the injected engine.
 *
 * input: { line, cost, qty, unitCost, label, category, key, context, engine,
 *          templates, tiers, customerTier, tierRules, now }
 *   context   ChannelEngineContext | raw record (normalized on demand) | null
 *   engine    { pricePart, resolveTemplatePrice?, templatePartDescriptor? }
 *             or a bare pricePart function
 *   templates / tiers / customerTier / tierRules — per-call overrides that
 *             merge over the context (line-level chart inputs).
 *
 * Passthrough rule: a line with NO own config AND no context returns
 * {priced:false, passthrough:true, sellPrice:<verbatim cost>}.
 */
export function wireChannelLineSell(input: any = {}): ChannelSellResult {
  const line = isRecord(input.line) ? input.line : (isRecord(input) && input.cost !== undefined && !input.line ? input : input.line);
  const src: any = isRecord(line) ? line : {};
  const chain: ChannelSellResult['chain'] = [];

  const cost = num(input.cost ?? input.lineCost ?? src.total_cost ?? src.cost);
  const rawQty = num(input.qty ?? src.qty ?? src.qty_letters ?? src.quantity, 0);
  const qty = rawQty > 0 ? rawQty : 1;
  const unitCost = Number.isFinite(Number(input.unitCost ?? input.unit_cost))
    ? num(input.unitCost ?? input.unit_cost)
    : (rawQty > 0 ? cost / rawQty : cost);
  const label = String(input.label ?? src.label ?? src.description ?? src.item_name ?? '');
  const category = String(input.category ?? src.category ?? src.category_key ?? '');
  const key = String(input.key ?? src.key ?? label ?? 'line');

  const context = channelEngineContext(input.context);
  const ctxPresent = !!context;
  chain.push({ step: 'context', detail: ctxPresent ? `context via ${context!.field || 'input'}` : 'no_context' });

  const config = channelLinePricingConfig(src);
  chain.push({
    step: 'detect',
    detail: config.configured ? `configured via ${config.via.join(',')}` : 'no line config',
  });

  const out = (r: Partial<ChannelSellResult>): ChannelSellResult => ({
    priced: false, passthrough: false, reason: null,
    sellPrice: cost, key, label, cost, qty, unitCost, category,
    via: config.via, chain,
    ...r,
  } as ChannelSellResult);

  if (!config.configured && !ctxPresent) {
    chain.push({ step: 'passthrough', detail: 'no tier/template config anywhere — cost echoed verbatim' });
    return out({ passthrough: true, reason: 'no_tier_config' });
  }

  const pricer = enginePricer(input.engine);
  if (!pricer) {
    chain.push({ step: 'passthrough', detail: 'engine not supplied — cost echoed verbatim' });
    return out({ passthrough: true, reason: 'engine_unavailable' });
  }

  // --- template layer: a bound PricingTemplate resolves through the caller-
  // injected resolveTemplatePrice, then templatePartDescriptor folds the
  // resolution into overrideRule vocabulary (pricingTemplateModel seam spec).
  let part = config.part;
  if (config.template !== null && config.template !== undefined) {
    const resolver = typeof input.engine?.resolveTemplatePrice === 'function'
      ? input.engine.resolveTemplatePrice : null;
    if (resolver) {
      const templatePart = isRecord(part) ? { ...part } : { ...(isRecord(src) ? src : {}) };
      if (isRecord(config.template)) templatePart.pricing_template = config.template;
      else templatePart.pricing_template_id = config.template;
      const res = resolver({
        part: templatePart,
        qty,
        base_price: unitCost,
        templates: input.templates ?? context?.templates,
        tiers: input.tiers ?? context?.tiers ?? input.customerTier ?? context?.customerTier,
        customer_tier: input.customerTier ?? context?.customerTier,
        template: isRecord(input.template) ? input.template : (isRecord(context?.template) ? context?.template : undefined),
        default_markup_pct: context?.defaultMarkupPct,
        minimum_charge: src.minimum_charge ?? context?.minimumCharge,
      });
      chain.push({
        step: 'template',
        detail: res?.applied === true
          ? `template priced (${res.source}:${res.pct_source ?? 'n/a'} -> unit ${round4(res.unit_price)})`
          : `template not applied (${res?.reason ?? 'unresolved'}) — engine chain prices`,
      });
      if (res?.applied === true) {
        const fold = typeof input.engine?.templatePartDescriptor === 'function'
          ? input.engine.templatePartDescriptor
          : (p: any) => p;
        part = fold(part ?? {}, res);
      }
    } else {
      chain.push({ step: 'template', detail: 'resolveTemplatePrice not supplied — ref left to engine chain' });
    }
  }

  const customerTier = src.customer_tier ?? src.customerTier
    ?? (isRecord(part) ? firstField(part, CUSTOMER_TIER_FIELDS) : undefined)
    ?? input.customerTier ?? context?.customerTier ?? null;
  const lineRules = TIER_RULES_FIELDS.reduce((acc: unknown[], f) => {
    const v = src[f] ?? (isRecord(part) ? part[f] : undefined);
    return Array.isArray(v) && v.length ? acc.concat(v) : acc;
  }, []);
  const tierRules = lineRules.length
    ? [...lineRules, ...(Array.isArray(input.tierRules) ? input.tierRules : []), ...(context?.tierRules ?? [])]
    : [...(Array.isArray(input.tierRules) ? input.tierRules : []), ...(context?.tierRules ?? [])];

  const priced = pricer({
    label, category, qty, unitCost,
    customerTier,
    tierRules,
    part,
    machine: config.machine ?? context?.machine,
    defaultMarkupPct: context?.defaultMarkupPct ?? 0,
    setupFee: firstFinite(src, SETUP_FEE_FIELDS) ?? context?.setupFee,
    minimumCharge: firstFinite(src, MIN_CHARGE_FIELDS) ?? context?.minimumCharge,
    taxable: typeof src.taxable === 'boolean' ? src.taxable : context?.taxable,
    taxPercent: firstFinite(src, TAX_PCT_FIELDS) ?? context?.taxPercent,
    // Line-level formula_modifiers already ride inside `part` (rule
    // modifiers). Passing them as caller `modifiers` too would double-apply
    // (engine runs rule modifiers THEN caller modifiers). Only caller/context
    // modifiers belong here.
    modifiers: input.modifiers ?? context?.modifiers,
    now: input.now,
  });

  chain.push({
    step: 'engine',
    detail: `pricePart -> ${priced?.priceSource ?? 'unknown'} via ${priced?.tier?.source ?? 'n/a'} (unit ${priced?.unitPrice ?? 'n/a'}, total ${priced?.total ?? 'n/a'})`,
  });

  return out({
    priced: true,
    sellPrice: num(priced?.total, cost),
    unitPrice: priced?.unitPrice,
    extension: priced?.extended ?? priced?.extension,
    priceSource: priced?.priceSource,
    tierSource: priced?.tier?.source,
    engine: priced,
  });
}

// ---------------------------------------------------------------------------
// wireChannelProjectSell — roll the cost lines up
// ---------------------------------------------------------------------------

export interface ChannelProjectSell {
  /** True when at least one line was engine-priced. */
  priced: boolean;
  /** True when EVERY line passed through (byte-identical to today's sum). */
  allPassthrough: boolean;
  /** Sum of line sellPrices — verbatim cost sum when allPassthrough. */
  sellTotal: number;
  /** Σ raw line costs (cost side echo — authoritative module math). */
  costTotal: number;
  lines: ChannelSellResult[];
  pricedCount: number;
  passthroughCount: number;
  /** The normalized context actually used (null when none). */
  context: ChannelEngineContext | null;
  chain: Array<{ step: string; detail: string }>;
}

/**
 * Run wireChannelLineSell over a set of channel cost lines.
 * `lines` may be channelCostLines() output or plain {line|cost|qty|...}
 * objects. All-passthrough -> sellTotal is the VERBATIM cost sum.
 */
export function wireChannelProjectSell(input: any = {}): ChannelProjectSell {
  const list: any[] = Array.isArray(input.lines) ? input.lines : [];
  const context = channelEngineContext(input.context);
  const chain: ChannelProjectSell['chain'] = [{
    step: 'context',
    detail: context ? `context via ${context.field || 'input'}` : 'no_context',
  }];

  const lines = list.map((l: any, i: number) =>
    wireChannelLineSell({
      key: l?.key ?? `line:${i}`,
      line: isRecord(l?.line) ? l.line : l,
      cost: l?.cost ?? l?.total_cost,
      qty: l?.qty,
      unitCost: l?.unitCost,
      label: l?.label,
      category: l?.category ?? l?.category_key,
      context,
      engine: input.engine,
      templates: input.templates,
      tiers: input.tiers,
      customerTier: input.customerTier,
      tierRules: input.tierRules,
      template: input.template,
      now: input.now,
    }));

  const pricedCount = lines.filter((l) => l.priced).length;
  const passthroughCount = lines.length - pricedCount;
  const allPassthrough = pricedCount === 0;
  const costTotal = lines.reduce((s, l) => s + l.cost, 0);
  // Verbatim sum when nothing priced (byte-identical); round2 money once the
  // engine owns any line.
  const sellTotal = allPassthrough
    ? lines.reduce((s, l) => s + l.sellPrice, 0)
    : round2(lines.reduce((s, l) => s + l.sellPrice, 0));

  chain.push({
    step: 'rollup',
    detail: allPassthrough
      ? `all ${lines.length} lines passthrough — sellTotal is verbatim cost sum`
      : `${pricedCount} priced / ${passthroughCount} passthrough -> sellTotal ${sellTotal}`,
  });

  return {
    priced: pricedCount > 0,
    allPassthrough,
    sellTotal,
    costTotal,
    lines,
    pricedCount,
    passthroughCount,
    context,
    chain,
  };
}

// ---------------------------------------------------------------------------
// channelEngineEconomics — the customerPricing.sourceProjectEconomics seam
// ---------------------------------------------------------------------------

export interface ChannelEngineEconomics {
  /** True when engine pricing produced the customerPrice. */
  wired: boolean;
  /** True when nothing was configured — caller keeps today's economics. */
  passthrough: boolean;
  reason: string | null;
  /** Cost side — echoed verbatim (module math stays authoritative). */
  internalCost: number;
  /** Sell side — engine sellTotal when wired, echoed fallback otherwise. */
  customerPrice: number;
  sell: ChannelProjectSell | null;
  lines: ChannelCostLine[];
  context: ChannelEngineContext | null;
  chain: Array<{ step: string; detail: string }>;
}

/**
 * Boundary helper for `sourceProjectEconomics('channel_letters', record)`.
 *
 * Returns {wired:false, passthrough:true} unless the record carries engine
 * config — the caller then returns today's {internalCost, customerPrice}
 * byte-identically. When wired, customerPrice is the engine sellTotal over
 * the record's cost lines; internalCost echoes the caller's module-computed
 * value untouched.
 */
export function channelEngineEconomics(input: any = {}): ChannelEngineEconomics {
  const record = input.record;
  const chain: ChannelEngineEconomics['chain'] = [];
  const done = (r: Partial<ChannelEngineEconomics>): ChannelEngineEconomics => ({
    wired: false, passthrough: false, reason: null,
    internalCost: num(input.internalCost),
    customerPrice: num(input.customerPrice),
    sell: null, lines: [], context: null, chain,
    ...r,
  } as ChannelEngineEconomics);

  if (!isRecord(record)) {
    chain.push({ step: 'passthrough', detail: 'no record' });
    return done({ passthrough: true, reason: 'no_record' });
  }

  const context = channelEngineContext(input.context ?? record);
  const lines = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : channelCostLines(record);
  if (!lines.length) {
    chain.push({ step: 'passthrough', detail: 'record produced no cost lines' });
    return done({ passthrough: true, reason: 'no_cost_lines', context });
  }

  const anyLineConfig = lines.some((l: any) =>
    channelLinePricingConfig(isRecord(l?.line) ? l.line : l).configured);
  chain.push({
    step: 'detect',
    detail: `${lines.length} cost lines; context ${context ? `via ${context.field}` : 'absent'}; line config ${anyLineConfig ? 'present' : 'absent'}`,
  });
  if (!context && !anyLineConfig) {
    chain.push({ step: 'passthrough', detail: 'no engine config anywhere — byte-identical' });
    return done({ passthrough: true, reason: 'no_tier_config', lines, context });
  }

  const sell = wireChannelProjectSell({
    lines, context, engine: input.engine,
    templates: input.templates ?? context?.templates,
    tiers: input.tiers ?? context?.tiers,
    customerTier: input.customerTier ?? context?.customerTier,
    tierRules: input.tierRules,
    now: input.now,
  });
  chain.push(...sell.chain);
  if (!sell.priced) {
    return done({ passthrough: true, reason: 'no_priced_lines', sell, lines, context });
  }
  chain.push({
    step: 'wired',
    detail: `engine customerPrice ${sell.sellTotal} over internalCost ${num(input.internalCost)} (${sell.pricedCount}/${lines.length} priced)`,
  });
  return done({
    wired: true,
    customerPrice: sell.sellTotal,
    sell, lines, context,
  });
}

/** Probe: does this record/line set carry engine config? (admin UI helper). */
export function channelEngineConfigured(source: any, lines?: any[]): boolean {
  if (channelEngineContext(source)) return true;
  const list = Array.isArray(lines) ? lines : [];
  return list.some((l: any) =>
    channelLinePricingConfig(isRecord(l?.line) ? l.line : l).configured);
}

// Vinyl module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23b) — pure TS,
// ZERO imports, NO IO. Bundles clean for Deno base44 functions and the Vite
// frontend (frontend-shared-modules allowlist).
//
// What this does: the vinyl module's COST math (estimator/vinyl/vinylCalc.js
// calcVinylProject, vinylEstimator/vinylNestingCalculator.calculateVinylProject,
// rollupVinylProject) stays authoritative. This wire only re-prices the SELL
// side of vinyl lines that carry a pricing-tier/template config. The engine is
// INJECTED by the caller ({ pricePart, resolveTemplatePrice,
// templatePartDescriptor } from base44/shared/pricingEngine.ts +
// pricingTemplateModel.ts) so this file stays import-free per shared-model
// convention.
//
// ZERO-REGRESSION CONTRACT: a vinyl record whose lines carry no engine-vocab
// pricing config resolves { applied:false, passthrough:true,
// customer_price === baselineSell } — the caller returns the module's own
// sell price verbatim (byte-identical at the aioPricing/customerPricing seam).
// When at least one line carries config, that line's share of the module sell
// is replaced by the engine-priced extension; un-configured lines keep their
// exact baseline contribution:
//
//   remainder      = baselineSell - configuredCostSum * (1 + markupPct/100)
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
//
// The module markup is linear over the aggregate subtotal, so each configured
// line's baseline contribution is exactly lineCost * (1 + markupPct/100) —
// subtracting it cannot disturb the other lines' sell dollars. markupPct
// defaults to record.markup_percent (the percent that produced markup_amount),
// falling back to markup_amount/subtotal when the percent field is absent.
//
// ---------------------------------------------------------------------------
// Activation contract — "a part/line carrying a pricing-tier config"
// ---------------------------------------------------------------------------
// A vinyl line (record.items[] row — the persisted flat list — or a
// workflows[].items[] row when the flat list is empty) is engine-priced when
// its resolved descriptor carries at least one pricing-engine field:
//
//   fixed_price | price_override | override_price | flat_price   pinned unit sell
//   tier_ref | tier_ref_id | tier | tier_name | pricing_tier_ref  bound tier row
//   per_unit_breaks | unit_breaks | qty_breaks                    qty chart
//   pricing_template_id | template_id | margin_template_id |
//     pricing_template_name | template_name | pricing_template | template
//                                                              bound PricingTemplate
//   global_pricing_tier_id | pricing_tier_id | tier_set_id |
//     pricing_tier_set_id | pricing_rule_set_id | global_tier_id |
//     global_pricing_tier_name | pricing_tier_name | tier_set_name
//                                                              bound GlobalPricingTier
//   market_retail | retail | retail_price | list_price |
//     market_discount_pct | retail_discount_pct                 market-based pricing
//   pricing_mode | price_mode | mode   (engine tokens 'market' | 'market_based'
//     | 'market-based' | 'retail' | 'retail_minus_discount' | 'fixed' |
//     'fixed_price' | 'flat' ONLY — vinyl unit enums like 'per_sqft' /
//     'per_roll' / 'per_linear_foot' / 'per_piece' are NOT pricing config)
//   markup_pct | markup | markup_percent                        part markup
//   minimum_charge | min_charge | minimum | setup_fee_floor     extension floor
//   setup_fee | setupFee | setup_fee_flat                       flat sell fee
//   formula_modifiers                                           ordered unit-price ops
//   machine | machine_override                                  descriptor w/ engine fields
//   customer_tier                                               line-scoped tier pin
//   tier_rules | tierRules | tier_matrix | templates |
//     pricing_templates | tiers                                 line-embedded registries
//   pricing | price_config | engine_pricing | pricing_config |
//     engine_price                                              nested config block
//
// Descriptor merge per line (weakest -> strongest):
//   flat item fields  <-  project engine_pricing.items[<line key>]  <-
//   item.pricing | .price_config | .engine_pricing | .pricing_config |
//   .engine_price nested block.
//
// Project-level context carrier (record.engine_pricing / .pricing_context /
// .engine_context / .pricing_engine — tolerated extras):
//   customer_tier, tier_rules | tierRules | tier_matrix, templates,
//   tiers | tier_catalog, default_markup_pct | defaultMarkupPct, now,
//   items | lines: { <item id|item_id|key|index>: <part descriptor> }.
// Caller-supplied `context` always outranks the record-embedded block; the
// record's saved Markup-Tier snapshot (customer_pricing.tier_number) is the
// weakest customer-tier source.
//
// Cost-base rule (safety): only lines with a finite numeric cost field
// (item_total_cost | line_total_cost | total_cost | extended_cost | line_cost |
// item_cost | cost | computed_cost) can be engine-priced — the wire must
// subtract exactly the baseline sell it replaces. A configured line without a
// cost base is SKIPPED (skipped_no_cost warning, baseline untouched) rather
// than double-charging or zeroing sell dollars.
//
// qty: item.quantity | qty | count, default 1 — 0 is honored (extension 0,
// engine minimum never fires on extension <= 0). unitCost = lineCost/qty for
// qty > 0 else the raw lineCost. The whole pipeline never throws; every
// resolution step is echoed in `chain` for transparency.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/** Line cost-base spellings (vinylCalc's item_total_cost first). */
const LINE_COST_FIELDS = [
  'item_total_cost', 'line_total_cost', 'total_cost', 'extended_cost',
  'line_cost', 'item_cost', 'cost', 'computed_cost',
] as const;

const LINE_QTY_FIELDS = ['quantity', 'qty', 'count'] as const;

const LINE_LABEL_FIELDS = ['label', 'description', 'name', 'item_name', 'part_name'] as const;

const LINE_KEY_FIELDS = ['id', 'item_id', 'part_id', 'key', 'line_id'] as const;

const LINE_CATEGORY_FIELDS = ['category_key', 'category', 'part_category', 'pricing_category'] as const;

/** Project record blocks that may carry engine context + per-line overrides. */
const ENGINE_BLOCK_FIELDS = ['engine_pricing', 'pricing_context', 'engine_context', 'pricing_engine'] as const;

/** Nested per-item config blocks. */
const NESTED_CONFIG_FIELDS = ['pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price'] as const;

/** Map inside the project block keyed by line key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Pricing-mode tokens that count as engine config (unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog'] as const;

/**
 * Flat item fields the engine can read — copied into the line descriptor.
 * (Field names only; presence does not by itself mark the line configured —
 * see descriptorHasPricingContent.)
 */
export const VINYL_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  'unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

const anyBlankSafeField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstField(rec, [f]) !== undefined);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a unit-enum pricing_mode ('per_sqft') or
 * a bare machine name must NOT flip the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// vinyl record -> normalized lines
// ---------------------------------------------------------------------------

export interface VinylWireLine {
  /** Stable key — item id, else positional workflow tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored). null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The raw vinyl item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'workflows' = nested workflow items. */
  origin: 'items' | 'workflows' | 'caller';
  workflow_id: string;
}

const lineKey = (item: Record<string, unknown>, index: number, workflowId = ''): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return workflowId ? `${workflowId}:${index}` : `idx-${index}`;
};

/**
 * Normalize a VinylProject-like record to the wire's line list.
 * `record.items` (the persisted flat list) wins when non-empty — the
 * workflows[].items it duplicates are never counted twice. Only when the flat
 * list is absent/empty do nested workflow items supply lines (legacy records).
 */
export function vinylRecordLines(record: unknown): VinylWireLine[] {
  if (!isRecord(record)) return [];
  const flat = Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : [];
  const source = flat.length
    ? flat.map((item, index) => ({ item, index, workflowId: asString(item.workflow_id) }))
    : (Array.isArray(record.workflows) ? (record.workflows as unknown[]) : [])
      .flatMap((wf: unknown) => {
        if (!isRecord(wf)) return [] as Array<{ item: Record<string, unknown>; index: number; workflowId: string }>;
        const wfId = asString(wf.id ?? wf.workflow_id ?? wf.name);
        return (Array.isArray(wf.items) ? (wf.items as unknown[]) : [])
          .filter(isRecord)
          .map((item: Record<string, unknown>, index: number) => ({ item, index, workflowId: wfId }));
      });

  const origin: VinylWireLine['origin'] = flat.length ? 'items' : 'workflows';
  return source.map(({ item, index, workflowId }, position) => ({
    key: lineKey(item, index, workflowId),
    index: position,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: firstFinite(item, LINE_COST_FIELDS),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin,
    workflow_id: workflowId,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface VinylPricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (the same percent that produced markup_amount — so a
 * configured-but-unresolved line naturally lands on its own baseline).
 */
export function vinylPricingContextOf(record: unknown, callerContext: unknown = null): VinylPricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function vinylLineDescriptor(line: VinylWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as VinylWireLine)?.item)
    ? (line as VinylWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of VINYL_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as VinylWireLine)?.key]) ? lineMap[(line as VinylWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as VinylWireLine)?.index)]) ? lineMap[asString((line as VinylWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface VinylConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which vinyl lines carry pricing-engine config. Cheap and
 * side-effect free; callers may use it to decide whether engine resolution is
 * needed at all.
 */
export function vinylConfigScan(record: unknown, lines?: VinylWireLine[]): VinylConfigScan {
  const wireLines = Array.isArray(lines) ? lines : vinylRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = vinylLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolveVinylSellPricing
// ---------------------------------------------------------------------------

export interface VinylWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface VinylSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface VinylSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: VinylSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: VinylSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: VinylSellLineResult[],
  chain: VinylSellPricingResult['chain'],
  warnings: string[],
  contextUsed: VinylSellPricingResult['context_used'],
): VinylSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the vinyl project sell price through the injected pricing engine.
 *
 * input.record          VinylProject-like (items[] and/or workflows[].items[])
 * input.lines           optional explicit VinylWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.subtotal), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal
 * input.context         vinylPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveVinylSellPricing(input: any = {}): VinylSellPricingResult {
  const warnings: string[] = [];
  const chain: VinylSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = vinylPricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: VinylWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: VinylWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : vinylRecordLines(rec);

  const scan = vinylConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: VinylSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = vinylLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : firstFinite(rawItem, LINE_COST_FIELDS);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: VinylSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Brick & Stone module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23c) —
// pure TS, ZERO imports, NO IO. Bundles clean for Deno base44 functions and
// the Vite frontend (frontend-shared-modules allowlist).
//
// What this does: the brick module's COST math (estimator/brick/brickCalc.js
// calcBrickStoneProject — material_cost + mortar_cost + labor_cost -> subtotal
// -> markup_amount -> total_cost) stays authoritative. This wire only
// re-prices the SELL side of brick projects that carry an engine context
// block or component-scoped pricing config. The engine is INJECTED by the
// caller ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ---------------------------------------------------------------------------
// ZERO-REGRESSION CONTRACT
// ---------------------------------------------------------------------------
// A BrickStoneProject record carrying no engine-vocab config resolves
// { applied:false, passthrough:true, customer_price === baselineSell } — the
// caller returns the module's own sell price VERBATIM (byte-identical, no
// float ops, at the customerPricing.sourceProjectEconomics seam). The record's
// own cost/rate/geometry fields (material_cost, mortar_cost, labor_cost,
// subtotal, markup_amount, markup_percent, mortar_bag_cost, bricks_per_hour,
// labor_rate_per_hour, waste_factor, mortar_gap, calculated_*, derived dims)
// are COST-side inputs — they are never scanned for engine config (reading
// them would mark every saved record "configured": markup_percent is the
// percent that produced markup_amount, so it only feeds the engine as the
// DEFAULT markup, exactly like the vinyl wire). A legacy saved
// customer_pricing Markup-Tier snapshot alone never engages — it only feeds
// the context block as the weakest customer-tier hint.
//
// ---------------------------------------------------------------------------
// Entity contract — BrickStoneProject.jsonc (module key 'brick_stone')
// ---------------------------------------------------------------------------
//   material_cost, mortar_cost, labor_cost, labor_hours,
//   mortar_bags_needed, calculated_bricks, calculated_surface_area,
//   subtotal, markup_amount, markup_percent, total_cost,
//   customer_pricing {applied, tier_number, tier_name, total, lines[] — the
//   saved Markup-Tier snapshot; never carries engine_context/pricing_engine}
//
//   Sum invariant: material_cost + mortar_cost + labor_cost == subtotal
//   (brickCalc.js) == the internalCost basis sourceProjectEconomics computes.
//
// Cost-line projection (brickCostLines) — granular mirror of
// categorizeBrickStoneProject (projectCategorizer.jsx): the categorizer rolls
// material_cost + mortar_cost into one 'outsourced_fab' materials line and
// labor_cost into 'outsourced_services'; the wire keeps per-component
// granularity so component-scoped config prices on its own:
//   'material'  cost=material_cost  qty=calculated_bricks   cat outsourced_fab
//   'mortar'    cost=mortar_cost    qty=mortar_bags_needed  cat outsourced_fab
//   'labor'     cost=labor_cost     qty=labor_hours         cat outsourced_services
// A component produces a line only when its cost field is FINITE (a present
// zero is a real line; absent/non-numeric drops the slot — a brand-new record
// with no computed costs yields no lines). qty honors an explicit 0
// (extension 0 — engine minimums never fire on extension <= 0, same as the
// vinyl wire); absent/non-finite qty fields fall back to 1, which keeps
// markup math identical because unitCost*qty == cost either way.
//
// ---------------------------------------------------------------------------
// Activation contract — what counts as engine config on a brick record
// ---------------------------------------------------------------------------
// 1. CONTEXT BLOCK (project-wide engagement — channel-wire parity):
//    record.pricing_engine | engine_pricing | pricing_tier_config |
//    pricing_context | engine_context, or
//    customer_pricing.engine_context | customer_pricing.pricing_engine.
//    Present-as-object => EVERY component line runs through the engine;
//    component descriptors override where present and unconfigured lines
//    price via the context chart / defaultMarkupPct (which defaults to
//    record.markup_percent — the same percent that produced the baseline
//    tail, so an unconfigured line lands back on its own baseline).
// 2. COMPONENT-SCOPED LINE CONFIG (no context block): only the configured
//    component reprices; every other component keeps its exact baseline
//    contribution. Descriptor merge per line key K in {material,mortar,labor}
//    (weakest -> strongest):
//      a. flat prefixed record fields   `${K}_<engineField>`
//         (labor_markup_pct, material_fixed_price, mortar_tier_ref,
//          material_market_retail, labor_pricing_template_id, ...)
//      b. an inline descriptor carried on an explicit input.lines[] row
//      c. context-block line map        block.items|lines|line_config|
//                                       item_config[K] (numeric index ok)
//      d. nested component blocks       ${K}_pricing | ${K}_price_config |
//                                       ${K}_engine_pricing |
//                                       ${K}_pricing_config |
//                                       ${K}_engine_price |
//                                       ${K}_tier_config | ${K}_sell_pricing
//    A top-level record.pricing|part|... descriptor is deliberately NOT
//    scanned — a flat aggregate record has no unambiguous line owner for a
//    pinned unit price, and scanning raw record fields would trip on legacy
//    cost fields.
//
// Engine vocabulary inside a descriptor (else it is NOT config -> the line
// passes through at baseline):
//   fixed_price|price_override|override_price|flat_price   >0 pinned unit sell
//   tier_ref|tier_ref_id|pricing_tier_ref|bound_tier|tier|tier_name
//   per_unit_breaks|unit_breaks|qty_breaks                 qty chart
//   pricing_template_id|template_id|margin_template_id|
//     pricing_template_name|template_name|pricing_template|template
//   global_pricing_tier_id|pricing_tier_id|tier_set_id|pricing_tier_set_id|
//     pricing_rule_set_id|global_tier_id|global_pricing_tier_name|
//     pricing_tier_name|tier_set_name                      tier-set refs
//   market_retail|retail|retail_price|list_price           >0 market retail
//   market_discount_pct|retail_discount_pct
//   markup_pct|markup|markup_percent                       nonzero only
//   minimum_charge|min_charge|minimum|setup_fee_floor      extension floor
//   setup_fee|setupFee|setup_fee_flat                      flat sell fee
//   formula_modifiers|modifiers                            ordered unit-price ops
//   pricing_mode|price_mode|mode|active_mode               RECOGNIZED tokens
//     only ('market','market_based','market-based','retail',
//     'retail_minus_discount','fixed','fixed_price','flat','cost_plus',
//     'cost-plus','costplus','markup','tier','tier_markup','tiered') —
//     brick unit enums like 'per_brick'/'per_bag'/'per_hour' are NOT config
//   machine|machine_override|machine_pricing|equipment_pricing
//     (counts only when the descriptor itself carries engine fields)
//   customer_tier|customerTier                             line-scoped tier pin
//   tier_rules|tierRules|rules|matrix|matrix_rows|rows|pricing_matrix
//   templates|pricing_templates | tiers|tier_catalog|markup_tiers
//                                                          embedded registries
//   interpolate_breaks|interpolateBreaks|interpolate|
//     break_interpolation                                  qty-chart interpolation
//
// Caller-supplied `context` registries (tierRules, templates, tiers,
// customerTier, defaultMarkupPct, now) merge OVER the record-embedded block
// but never constitute engagement by themselves — engagement requires a
// record-carried context block or component-scoped config.
//
// Composition (vinyl remainder model — the module markup is linear over the
// aggregate subtotal, so each priced line's baseline contribution is exactly
// lineCost * (1 + markupPct/100)):
//   remainder      = baselineSell - Σ pricedLineCost * (1 + markupPct/100)
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
// When a context block prices every line the remainder lands at ~0 and the
// engine owns the whole sell tail — including winning over a legacy saved
// customer_pricing snapshot (recorded in chain).
//
// The whole pipeline never throws; every step is echoed in `chain` and
// `warnings` for transparency. Configured lines without a finite cost base
// (possible only via an explicit input.lines[] override — brickCostLines only
// emits finite-cost components) are SKIPPED at baseline, never repriced blind.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/** Module keys the brick record answers to (moduleRegistry key first). */
export const BRICK_MODULE_KEYS = Object.freeze([
  'brick_stone', 'brick', 'brickstone', 'brick_stone_project', 'masonry',
] as const);

/**
 * The three module-authored cost components (brickCalc.js aggregation;
 * category keys mirror categorizeBrickStoneProject).
 */
const BRICK_COMPONENTS = [
  {
    key: 'material',
    label: 'Brick / Stone Material',
    costFields: ['material_cost', 'materials_cost'],
    qtyFields: ['calculated_bricks', 'brick_count'],
    category_key: 'outsourced_fab',
  },
  {
    key: 'mortar',
    label: 'Mortar',
    costFields: ['mortar_cost'],
    qtyFields: ['mortar_bags_needed', 'mortar_bags'],
    category_key: 'outsourced_fab',
  },
  {
    key: 'labor',
    label: 'Masonry Labor',
    costFields: ['labor_cost'],
    qtyFields: ['labor_hours'],
    category_key: 'outsourced_services',
  },
] as const;

export const BRICK_COMPONENT_KEYS: readonly string[] = Object.freeze(
  BRICK_COMPONENTS.map((c) => c.key),
);

/** Record-level fields probed for the engine context block (in order). */
const CONTEXT_BLOCK_FIELDS = [
  'pricing_engine', 'engine_pricing', 'pricing_tier_config', 'pricing_context', 'engine_context',
] as const;

/** customer_pricing sub-fields also probed (saved tier snapshot block). */
const NESTED_CONTEXT_FIELDS = ['engine_context', 'pricing_engine'] as const;

/** Map inside the context block keyed by component key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Per-component nested descriptor spellings: `${key}_<suffix>`. */
const COMPONENT_BLOCK_SUFFIXES = [
  'pricing', 'price_config', 'engine_pricing', 'pricing_config',
  'engine_price', 'tier_config', 'sell_pricing',
] as const;

/** Recognized pricing-mode tokens (channel-wire superset — unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
  'cost_plus', 'cost-plus', 'costplus', 'markup', 'tier', 'tier_markup', 'tiered',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers', 'modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode', 'active_mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override', 'machine_pricing', 'equipment_pricing'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix', 'rules', 'matrix', 'matrix_rows', 'rows', 'pricing_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog', 'markup_tiers'] as const;
const UNIT_FIELDS = ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'] as const;
const TAX_PCT_FIELDS = ['tax_percent', 'taxPercent'] as const;
const INTERPOLATE_FIELDS = ['interpolate_breaks', 'interpolateBreaks', 'interpolate', 'break_interpolation'] as const;
const DEFAULT_MARKUP_FIELDS = ['default_markup_pct', 'defaultMarkupPct', 'default_markup'] as const;

/**
 * Flat per-component engine spellings — on the record these ride the
 * `<component>_<field>` prefix; inside a nested/inline descriptor they are
 * the bare field names. Presence alone does not mark a line configured —
 * see descriptorHasPricingContent.
 */
export const BRICK_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  ...UNIT_FIELDS,
  ...TAX_PCT_FIELDS,
  ...INTERPOLATE_FIELDS,
  'taxable',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  const fixed = firstFinite(v, FIXED_FIELDS);
  const retail = firstFinite(v, MARKET_FIELDS);
  const markup = firstFinite(v, MARKUP_FIELDS);
  return (fixed !== null && fixed > 0)
    || (retail !== null && retail > 0)
    || (markup !== null && markup !== 0)
    || firstFinite(v, MIN_FIELDS) !== null
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? Channel-wire thresholds: fixed_price must be POSITIVE, markup must
 * be NONZERO (an explicit markup_pct:0 is not config), market retail must be
 * positive, chart/registry fields must be non-empty, mode tokens must be
 * recognized engine spellings. An empty pricing block, a unit-enum
 * pricing_mode ('per_brick'), or a bare machine name must NOT flip the
 * component out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  const fixed = firstFinite(d, FIXED_FIELDS);
  if (fixed !== null && fixed > 0) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (nonEmptyArrayField(d, BREAK_FIELDS)) return true;
  const retail = firstFinite(d, MARKET_FIELDS);
  if (retail !== null && retail > 0) return true;
  const discount = firstFinite(d, MARKET_DISCOUNT_FIELDS);
  if (discount !== null && discount !== 0) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  const markup = firstFinite(d, MARKUP_FIELDS);
  if (markup !== null && markup !== 0) return true;
  if (nonEmptyArrayField(d, FORMULA_FIELDS)) return true;
  if (firstFinite(d, MIN_FIELDS) !== null) return true;
  if (firstFinite(d, SETUP_FIELDS) !== null) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (nonEmptyArrayField(d, [...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => asString(firstField(d, [f])) !== '')) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// brick record -> normalized component lines
// ---------------------------------------------------------------------------

export interface BrickWireLine {
  /** Canonical component key — 'material' | 'mortar' | 'labor'. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Module-authored component cost. null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The component's raw record carrier (the project record itself). */
  item: Record<string, unknown> | null;
  /** Inline descriptor carried on an explicit input.lines[] override row. */
  descriptor?: Record<string, unknown> | null;
  /** 'components' = projected record fields; 'caller' = input.lines[]. */
  origin: 'components' | 'caller';
}

const componentOf = (key: unknown) =>
  BRICK_COMPONENTS.find((c) => c.key === lc(key)) ?? null;

/**
 * Project a BrickStoneProject-like record into granular component cost lines.
 * Component slots emit in canonical order (material, mortar, labor); a slot
 * produces a line only when its cost field is finite. Sum of line costs ==
 * the record's internalCost basis (material + mortar + labor == subtotal).
 */
export function brickCostLines(record: unknown): BrickWireLine[] {
  if (!isRecord(record)) return [];
  const lines: BrickWireLine[] = [];
  BRICK_COMPONENTS.forEach((comp) => {
    const cost = firstFinite(record, comp.costFields);
    if (cost === null) return;
    const qty = firstFinite(record, comp.qtyFields) ?? 1;
    lines.push({
      key: comp.key,
      index: lines.length,
      label: comp.label,
      qty,
      cost,
      category_key: comp.category_key,
      item: record,
      origin: 'components',
    });
  });
  return lines;
}

// ---------------------------------------------------------------------------
// project context carrier + per-component descriptor
// ---------------------------------------------------------------------------

const contextBlockOf = (record: unknown): { block: Record<string, unknown> | null; field: string } => {
  const rec = isRecord(record) ? record : {};
  for (const f of CONTEXT_BLOCK_FIELDS) {
    if (isRecord(rec[f])) return { block: rec[f] as Record<string, unknown>, field: f };
  }
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : null;
  if (cp) {
    for (const f of NESTED_CONTEXT_FIELDS) {
      if (isRecord(cp[f])) return { block: cp[f] as Record<string, unknown>, field: `customer_pricing.${f}` };
    }
  }
  return { block: null, field: '' };
};

export interface BrickPricingContext {
  /** Marker so callers can pass the normalized context back without a rescan. */
  __brickPricingContext?: true;
  /** True when the RECORD carries an engine context block (engagement gate —
   * caller-supplied registries alone never engage). */
  hasContextBlock: boolean;
  /** Which record field supplied the block ('' when none). */
  field: string;
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  /** Shop fallback markup pct — defaults to record.markup_percent. */
  defaultMarkupPct: number;
  /** Context-level machine descriptor. */
  machine: unknown;
  /** Context-level floors/fees/tax applied to every engine-priced line. */
  taxable: boolean | undefined;
  taxPercent: number;
  setupFee: number;
  minimumCharge: number;
  modifiers: unknown[] | undefined;
  /** Line map inside the context block ({<component key>: descriptor}). */
  lineMap: Record<string, unknown> | null;
  now: unknown;
  /** The raw context block (audit echo). */
  raw: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > the record's pricing_engine-style block > the saved
 * Markup-Tier snapshot tier_number > record.markup_percent as the default
 * markup. `hasContextBlock` records whether the record itself carries a block
 * — that (or component-scoped config) is what engages the wire.
 */
export function brickPricingContextOf(record: unknown, callerContext: unknown = null): BrickPricingContext {
  const rec = isRecord(record) ? record : {};
  const caller = isRecord(callerContext) ? callerContext : {};
  if ((callerContext as BrickPricingContext)?.__brickPricingContext === true) {
    return callerContext as BrickPricingContext;
  }

  const { block, field } = contextBlockOf(rec);
  const blk = block ?? {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(blk, [...TIER_CONTEXT_FIELDS, 'tier'])
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, EMBEDDED_RULE_FIELDS)
    ?? firstArray(blk, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, EMBEDDED_TEMPLATE_FIELDS)
    ?? firstArray(blk, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, EMBEDDED_TIER_CATALOG_FIELDS)
    ?? firstArray(blk, EMBEDDED_TIER_CATALOG_FIELDS)
    ?? [];

  const defaultMarkupPct = firstFinite(caller, DEFAULT_MARKUP_FIELDS.concat('markup_pct' as const))
    ?? firstFinite(blk, DEFAULT_MARKUP_FIELDS.concat(MARKUP_FIELDS))
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  const taxable = typeof caller.taxable === 'boolean' ? caller.taxable
    : typeof blk.taxable === 'boolean' ? blk.taxable
    : lc(blk.taxable) === 'true' ? true
    : lc(blk.taxable) === 'false' ? false
    : undefined;

  const callerModifiers = firstArray(caller, FORMULA_FIELDS);
  const blockModifiers = firstArray(blk, FORMULA_FIELDS);

  return {
    __brickPricingContext: true,
    hasContextBlock: block !== null,
    field,
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct: num(defaultMarkupPct),
    machine: firstField(blk, MACHINE_FIELDS) ?? firstField(caller, MACHINE_FIELDS) ?? null,
    taxable,
    taxPercent: num(firstFinite(caller, TAX_PCT_FIELDS) ?? firstFinite(blk, TAX_PCT_FIELDS)),
    setupFee: num(firstFinite(caller, SETUP_FIELDS) ?? firstFinite(blk, SETUP_FIELDS)),
    minimumCharge: num(firstFinite(caller, MIN_FIELDS) ?? firstFinite(blk, MIN_FIELDS)),
    modifiers: callerModifiers ?? blockModifiers ?? undefined,
    lineMap: firstRecord(blk, ENGINE_LINE_MAP_FIELDS),
    now: caller.now ?? blk.now,
    raw: block,
  };
}

// ---------------------------------------------------------------------------
// per-component descriptor resolution
// ---------------------------------------------------------------------------

const componentNestedBlock = (record: unknown, key: string): Record<string, unknown> | null => {
  const rec = isRecord(record) ? record : {};
  for (const suffix of COMPONENT_BLOCK_SUFFIXES) {
    const f = `${key}_${suffix}`;
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

/**
 * Copy engine-vocab fields off a source record. When `prefix` is given the
 * source fields are `<prefix>_<field>` (the flat `<component>_<field>`
 * spellings on the project record); otherwise the bare field names (inline /
 * nested descriptors).
 */
const engineFieldsFrom = (src: unknown, prefix = ''): Record<string, unknown> => {
  const out: Record<string, unknown> = {};
  if (!isRecord(src)) return out;
  for (const f of BRICK_ENGINE_LINE_FIELDS) {
    const k = prefix ? `${prefix}_${f}` : f;
    if (src[k] !== undefined && src[k] !== null && src[k] !== '') out[f] = src[k];
  }
  return out;
};

/**
 * Per-component merged part descriptor (weakest -> strongest):
 *   flat `${key}_<field>` record fields  <-  inline descriptor on an
 *   input.lines[] row  <-  context-block items/lines map entry  <-
 *   nested `${key}_pricing`-style component block.
 * Returns null when no config source exists.
 */
export function brickLineDescriptor(line: BrickWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const key = lc((line as BrickWireLine)?.key);
  if (!componentOf(key)) return null;

  const rec = isRecord(record) ? record : {};
  const flat = engineFieldsFrom(rec, key);

  // An explicit input.lines[] row may carry its own config inline (bare field
  // spellings) or under .descriptor/.pricing — merged over the flat layer.
  const rawLine = isRecord(line) ? (line as Record<string, unknown>) : {};
  const ownInline = engineFieldsFrom(rawLine);
  const ownNested = firstRecord(rawLine, ['descriptor', 'pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price']);

  const { block } = contextBlockOf(rec);
  const lineMap = block ? firstRecord(block, ENGINE_LINE_MAP_FIELDS) : null;
  const mapEntry = lineMap
    ? (isRecord(lineMap[key]) ? lineMap[key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as BrickWireLine)?.index)]) ? lineMap[asString((line as BrickWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = componentNestedBlock(rec, key);

  const merged = {
    ...flat,
    ...ownInline,
    ...(ownNested ?? {}),
    ...(mapEntry ?? {}),
    ...(nested ?? {}),
  };
  if (!Object.keys(merged).length && !nested && !mapEntry && !ownNested) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface BrickConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which brick component lines carry pricing config. Cheap
 * and side-effect free; does NOT include context-block engagement (see
 * brickEngineConfigured for the full engagement probe).
 */
export function brickConfigScan(record: unknown, lines?: BrickWireLine[]): BrickConfigScan {
  const wireLines = Array.isArray(lines) ? lines : brickCostLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = brickLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

/**
 * Full engagement probe: does this record carry engine config? — a
 * record-carried context block OR at least one configured component line.
 * (admin UI badge helper / tests).
 */
export function brickEngineConfigured(record: unknown, lines?: BrickWireLine[]): boolean {
  if (contextBlockOf(record).block) return true;
  return brickConfigScan(record, lines).configured;
}

// ---------------------------------------------------------------------------
// resolveBrickSellPricing
// ---------------------------------------------------------------------------

export interface BrickWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface BrickSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  /** True when the line's own descriptor carries engine config. */
  configured: boolean;
  /** True when the engine priced the line (context engagement counts). */
  priced: boolean;
  /** 'context' = repriced by block engagement without own config. */
  priced_via: 'descriptor' | 'context' | null;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface BrickSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** True when a record-carried context block engaged the whole sell tail. */
  context_engaged: boolean;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: BrickSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    context_block: string;
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: BrickSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  contextEngaged: boolean,
  lines: BrickSellLineResult[],
  chain: BrickSellPricingResult['chain'],
  warnings: string[],
  contextUsed: BrickSellPricingResult['context_used'],
): BrickSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  context_engaged: contextEngaged,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the brick project sell price through the injected pricing engine.
 *
 * input.record          BrickStoneProject-like record
 * input.lines           optional explicit BrickWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.subtotal), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal
 * input.context         brickPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveBrickSellPricing(input: any = {}): BrickSellPricingResult {
  const warnings: string[] = [];
  const chain: BrickSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = brickPricingContextOf(rec, input.context);
  const contextUsed = {
    context_block: context.field || '',
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: BrickWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: BrickWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines.map((l: any, position: number) => ({
        key: asString(l?.key) || `line-${position}`,
        index: position,
        label: asString(l?.label) || componentOf(l?.key)?.label || `Component ${position + 1}`,
        qty: l?.qty !== undefined ? num(l.qty, 1) : (componentOf(l?.key) ? (firstFinite(rec, componentOf(l?.key)!.qtyFields) ?? 1) : 1),
        cost: l?.cost !== undefined ? toFiniteNumber(l.cost) : (componentOf(l?.key) ? firstFinite(rec, componentOf(l?.key)!.costFields) : toFiniteNumber(l?.item_total_cost ?? l?.line_total_cost ?? l?.total_cost ?? l?.cost)),
        category_key: asString(l?.category_key) || componentOf(l?.key)?.category_key || '',
        item: isRecord(l?.item) ? l.item : rec,
        descriptor: isRecord(l) ? l : null,
        origin: 'caller' as const,
      }))
    : brickCostLines(rec);

  const scan = brickConfigScan(rec, wireLines);
  const engaged = context.hasContextBlock || scan.configured;
  chain.push({
    layer: 'config_scan',
    hit: engaged,
    won: false,
    detail: context.hasContextBlock
      ? `context block via ${context.field}${scan.configured ? ` + ${scan.configuredCount} configured component(s)` : ''}`
      : scan.configured
        ? `${scan.configuredCount} of ${scan.lineCount} components carry pricing config`
        : `no pricing config on ${scan.lineCount} components`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, false, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, context.hasContextBlock, [], chain, warnings, contextUsed);
  if (!engaged) return passthroughResult('no_config', baselineSell, internalCost, markupPct, false, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, context.hasContextBlock, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: BrickSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const descriptor = brickLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Under context-block engagement the engine owns EVERY component line
    // (channel-wire parity); an unconfigured line then prices via the context
    // chart / default markup — landing back on its own baseline contribution.
    const enginePrices = configured || context.hasContextBlock;
    const cost = line.cost !== undefined ? line.cost : null;
    const qty = num(line.qty, 1);
    const base: BrickSellLineResult = {
      key: line.key || `line-${position}`,
      label: line.label || `Component ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      priced_via: null,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!enginePrices) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`component '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // tier-set chart resolves the unit price, then the descriptor adapter
    // encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...(descriptor ?? {}) };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `component '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`component '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? context.machine;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? (context.setupFee || undefined);
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? (context.minimumCharge || undefined);
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : context.modifiers;
    const taxable = typeof partDescriptor.taxable === 'boolean' ? partDescriptor.taxable : context.taxable;
    const taxPercent = firstFinite(partDescriptor, TAX_PCT_FIELDS) ?? (context.taxPercent || undefined);

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, UNIT_FIELDS)) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        taxable,
        taxPercent,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`component '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    base.priced_via = configured ? 'descriptor' : 'context';
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`component '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, context.hasContextBlock, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`priced components' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - priced baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    context_engaged: context.hasContextBlock,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// CNC module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23d) — pure TS,
// ZERO imports, NO IO. Bundles clean for Deno base44 functions and the Vite
// frontend (frontend-shared-modules allowlist).
//
// What this does: the CNC module's COST math stays authoritative — the
// persisted item machine_cost / labor_cost (CNCEstimator.jsx updateItem +
// calculateTotals; estimator/cnc/cncCalc.js calcCNCProject spells the same
// per-line total as item_total_cost) plus the project-level fixed_setup_cost
// and min-labor-floor adjustment inside record.total_cost. This wire only
// re-prices the SELL side of CNC lines that carry a pricing-tier/template
// config. The engine is INJECTED by the caller ({ pricePart,
// resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ZERO-REGRESSION CONTRACT: a CNC record whose lines carry no engine-vocab
// pricing config resolves { applied:false, passthrough:true,
// customer_price === baselineSell } — the caller returns the module's own
// sell price verbatim (byte-identical at the customerPricing seam). CNC
// records carry no module markup (total_cost is a pure cost total; the saved
// customer_pricing Markup-Tier snapshot is a separate layer), so the module
// markup factor is 1 and each configured line's baseline contribution is
// exactly its own line cost:
//
//   remainder      = baselineSell - Σ configured line cost
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
//
// Because the remainder only subtracts configured lines' costs, everything
// not repriced — un-configured lines, the fixed setup dollars, and any
// minimum-labor adjustment inside total_cost — keeps its exact baseline
// contribution. markupPct still honors input.markupPercent /
// record.markup_percent / markup_amount÷subtotal for forward parity with the
// other module wires; on today's CNC records it resolves to 0.
//
// ---------------------------------------------------------------------------
// Activation contract — "a line carrying a pricing-tier config"
// ---------------------------------------------------------------------------
// A CNC line (record.items[] row — the persisted flat list) is engine-priced
// when its resolved descriptor carries at least one pricing-engine field:
//
//   fixed_price | price_override | override_price | flat_price   pinned unit sell
//   tier_ref | tier_ref_id | tier | tier_name | pricing_tier_ref  bound tier row
//   per_unit_breaks | unit_breaks | qty_breaks                    qty chart
//   pricing_template_id | template_id | margin_template_id |
//     pricing_template_name | template_name | pricing_template | template
//                                                              bound PricingTemplate
//   global_pricing_tier_id | pricing_tier_id | tier_set_id |
//     pricing_tier_set_id | pricing_rule_set_id | global_tier_id |
//     global_pricing_tier_name | pricing_tier_name | tier_set_name
//                                                              bound GlobalPricingTier
//   market_retail | retail | retail_price | list_price |
//     market_discount_pct | retail_discount_pct                 market-based pricing
//   pricing_mode | price_mode | mode   (engine tokens 'market' | 'market_based'
//     | 'market-based' | 'retail' | 'retail_minus_discount' | 'fixed' |
//     'fixed_price' | 'flat' ONLY — CNC unit/type enums like 'panel' /
//     'lettering' / '3d_carving' / 'per_hour' / 'per_sheet' are NOT pricing
//     config; material_type / workholding_method / cut speeds / machine_cost /
//     labor_cost are cost-side fields and are never config)
//   markup_pct | markup | markup_percent                        part markup
//   minimum_charge | min_charge | minimum | setup_fee_floor     extension floor
//   setup_fee | setupFee | setup_fee_flat                       flat sell fee
//   formula_modifiers                                           ordered unit-price ops
//   machine | machine_override                                  descriptor w/ engine fields
//   customer_tier                                               line-scoped tier pin
//   tier_rules | tierRules | tier_matrix | templates |
//     pricing_templates | tiers                                 line-embedded registries
//   pricing | price_config | engine_pricing | pricing_config |
//     engine_price                                              nested config block
//
// Descriptor merge per line (weakest -> strongest):
//   flat item fields  <-  project engine_pricing.items[<line key>]  <-
//   item.pricing | .price_config | .engine_pricing | .pricing_config |
//   .engine_price nested block.
//
// Project-level context carrier (record.engine_pricing / .pricing_context /
// .engine_context / .pricing_engine — tolerated extras):
//   customer_tier, tier_rules | tierRules | tier_matrix, templates,
//   tiers | tier_catalog, default_markup_pct | defaultMarkupPct, now,
//   items | lines: { <item builder_item_id|id|key|index>: <part descriptor> }.
// Caller-supplied `context` always outranks the record-embedded block; the
// record's saved Markup-Tier snapshot (customer_pricing.tier_number) is the
// weakest customer-tier source.
//
// Cost-base rule (safety): only lines with a finite numeric cost base can be
// engine-priced — the wire must subtract exactly the baseline sell it
// replaces. CNC spells it two ways: a single-total field (item_total_cost |
// line_total_cost | total_cost | extended_cost | line_cost | item_cost |
// cost | computed_cost — calcCNCProject's item_total_cost first) or the
// persisted machine_cost + labor_cost component pair written by
// CNCEstimator's updateItem. A configured line without a cost base is
// SKIPPED (skipped_no_cost warning, baseline untouched) rather than
// double-charging or zeroing sell dollars.
//
// qty: item.quantity | qty | count, default 1 — 0 is honored (extension 0,
// engine minimum never fires on extension <= 0). Note the page pins
// lettering items to quantity 1 (num_letters is already folded into the
// persisted cut length / machine time) so quantity semantics stay faithful
// to the module's own math. unitCost = lineCost/qty for qty > 0 else the raw
// lineCost. The whole pipeline never throws; every resolution step is echoed
// in `chain` for transparency.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/**
 * Line cost-base spellings (single-total fields; calcCNCProject's
 * item_total_cost first). When none is present the wire falls back to the
 * persisted machine_cost + labor_cost component pair — the shape
 * CNCEstimator.jsx actually saves on each item.
 */
const LINE_COST_FIELDS = [
  'item_total_cost', 'line_total_cost', 'total_cost', 'extended_cost',
  'line_cost', 'item_cost', 'cost', 'computed_cost',
] as const;

/** CNC cost components persisted per item by the estimator page. */
const LINE_COST_COMPONENT_FIELDS = ['machine_cost', 'labor_cost'] as const;

const LINE_QTY_FIELDS = ['quantity', 'qty', 'count'] as const;

const LINE_LABEL_FIELDS = ['description', 'label', 'name', 'item_name', 'part_name'] as const;

/** builder_item_id is the stable hidden row identity seeded by the page. */
const LINE_KEY_FIELDS = ['builder_item_id', 'id', 'item_id', 'part_id', 'key', 'line_id'] as const;

/** item_type (panel|lettering|3d_carving) doubles as the pricing category. */
const LINE_CATEGORY_FIELDS = ['category_key', 'category', 'part_category', 'pricing_category', 'item_type'] as const;

/** Project record blocks that may carry engine context + per-line overrides. */
const ENGINE_BLOCK_FIELDS = ['engine_pricing', 'pricing_context', 'engine_context', 'pricing_engine'] as const;

/** Nested per-item config blocks. */
const NESTED_CONFIG_FIELDS = ['pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price'] as const;

/** Map inside the project block keyed by line key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Pricing-mode tokens that count as engine config (unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog'] as const;

/**
 * Flat item fields the engine can read — copied into the line descriptor.
 * (Field names only; presence does not by itself mark the line configured —
 * see descriptorHasPricingContent.)
 */
export const CNC_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  'unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a CNC unit/type enum (pricing_mode
 * 'per_hour', item_type 'panel', material_type 'Wood') or a bare machine name
 * must NOT flip the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// CNC record -> normalized lines
// ---------------------------------------------------------------------------

export interface CncWireLine {
  /** Stable key — builder_item_id, else item id, else positional tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored). null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The raw CNC item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'caller' = input.lines override. */
  origin: 'items' | 'caller';
}

const lineKey = (item: Record<string, unknown>, index: number): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return `idx-${index}`;
};

/**
 * The line's module-authored cost base: a persisted single-total field first
 * (calcCNCProject's item_total_cost), else the machine_cost + labor_cost
 * component pair CNCEstimator writes per item, else null (no cost base).
 */
const lineCostOf = (item: Record<string, unknown>): number | null => {
  const direct = firstFinite(item, LINE_COST_FIELDS);
  if (direct !== null) return direct;
  const machine = toFiniteNumber(item.machine_cost);
  const labor = toFiniteNumber(item.labor_cost);
  if (machine === null && labor === null) return null;
  return num(machine) + num(labor);
};

/**
 * Normalize a CNCProject-like record to the wire's line list. The persisted
 * flat `record.items` list is the only line source — the module has no
 * nested workflow structures.
 */
export function cncRecordLines(record: unknown): CncWireLine[] {
  if (!isRecord(record)) return [];
  const flat = Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : [];
  return flat.map((item, index) => ({
    key: lineKey(item, index),
    index,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || `Item ${index + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: lineCostOf(item),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin: 'items' as const,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface CncPricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (absent on CNC records today, so 0 — a configured-but-
 * unresolved line then naturally lands on its own cost baseline).
 */
export function cncPricingContextOf(record: unknown, callerContext: unknown = null): CncPricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function cncLineDescriptor(line: CncWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as CncWireLine)?.item)
    ? (line as CncWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of CNC_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as CncWireLine)?.key]) ? lineMap[(line as CncWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as CncWireLine)?.index)]) ? lineMap[asString((line as CncWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface CncConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which CNC lines carry pricing-engine config. Cheap and
 * side-effect free; callers may use it to decide whether engine resolution is
 * needed at all.
 */
export function cncConfigScan(record: unknown, lines?: CncWireLine[]): CncConfigScan {
  const wireLines = Array.isArray(lines) ? lines : cncRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = cncLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolveCncSellPricing
// ---------------------------------------------------------------------------

export interface CncWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface CncSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface CncSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: CncSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: CncSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: CncSellLineResult[],
  chain: CncSellPricingResult['chain'],
  warnings: string[],
  contextUsed: CncSellPricingResult['context_used'],
): CncSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the CNC project sell price through the injected pricing engine.
 *
 * input.record          CNCProject-like (items[])
 * input.lines           optional explicit CncWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.total_cost), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal, else 0 (CNC today)
 * input.context         cncPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveCncSellPricing(input: any = {}): CncSellPricingResult {
  const warnings: string[] = [];
  const chain: CncSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = cncPricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: CncWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: CncWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : cncRecordLines(rec);

  const scan = cncConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: CncSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = cncLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : lineCostOf(rawItem);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: CncSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Laser module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23e) — pure TS,
// ZERO imports, NO IO. Bundles clean for Deno base44 functions and the Vite
// frontend (frontend-shared-modules allowlist).
//
// What this does: the Laser module's COST math stays authoritative — the
// persisted item machine_cost / labor_cost (LaserEstimator.jsx updateItem +
// calculateTotals writes the mm/sec-derived per-line pair; the shared
// estimator/laser/laserCalc.js calcLaserProject spells the same per-line
// total as item_total_cost) plus the project-level fixed_setup_hours x
// labor_rate setup labor folded into total_labor_cost and the
// fixed_material_setup_cost supplies inside record.total_cost. This wire
// only re-prices the SELL side of laser lines that carry a
// pricing-tier/template config. The engine is INJECTED by the caller
// ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ZERO-REGRESSION CONTRACT: a laser record whose lines carry no engine-vocab
// pricing config resolves { applied:false, passthrough:true,
// customer_price === baselineSell } — the caller returns the module's own
// sell price verbatim (byte-identical at the customerPricing seam). Laser
// records carry no module markup (total_cost is a pure cost total; the saved
// customer_pricing Markup-Tier snapshot is a separate layer), so the module
// markup factor is 1 and each configured line's baseline contribution is
// exactly its own line cost:
//
//   remainder      = baselineSell - Σ configured line cost
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
//
// Because the remainder only subtracts configured lines' costs, everything
// not repriced — un-configured lines, the fixed setup labor dollars, and the
// fixed material/supplies setup inside total_cost — keeps its exact baseline
// contribution. markupPct still honors input.markupPercent /
// record.markup_percent / markup_amount÷subtotal for forward parity with the
// other module wires; on today's laser records it resolves to 0.
//
// ---------------------------------------------------------------------------
// Activation contract — "a line carrying a pricing-tier config"
// ---------------------------------------------------------------------------
// A laser line (record.items[] row — the persisted flat list) is
// engine-priced when its resolved descriptor carries at least one
// pricing-engine field:
//
//   fixed_price | price_override | override_price | flat_price   pinned unit sell
//   tier_ref | tier_ref_id | tier | tier_name | pricing_tier_ref  bound tier row
//   per_unit_breaks | unit_breaks | qty_breaks                    qty chart
//   pricing_template_id | template_id | margin_template_id |
//     pricing_template_name | template_name | pricing_template | template
//                                                              bound PricingTemplate
//   global_pricing_tier_id | pricing_tier_id | tier_set_id |
//     pricing_tier_set_id | pricing_rule_set_id | global_tier_id |
//     global_pricing_tier_name | pricing_tier_name | tier_set_name
//                                                              bound GlobalPricingTier
//   market_retail | retail | retail_price | list_price |
//     market_discount_pct | retail_discount_pct                 market-based pricing
//   pricing_mode | price_mode | mode   (engine tokens 'market' | 'market_based'
//     | 'market-based' | 'retail' | 'retail_minus_discount' | 'fixed' |
//     'fixed_price' | 'flat' ONLY — laser unit/type enums like 'panel' /
//     'lettering' / 'engraving' / 'engrave_and_cut' / 'per_hour' /
//     'per_sheet' are NOT pricing config; material_type
//     (Acrylic|Wood|Leather), material_thickness, cut/engrave speeds,
//     machine_time_hours, handling_time_hours, machine_cost / labor_cost are
//     cost-side fields and are never config)
//   markup_pct | markup | markup_percent                        part markup
//   minimum_charge | min_charge | minimum | setup_fee_floor     extension floor
//   setup_fee | setupFee | setup_fee_flat                       flat sell fee
//   formula_modifiers                                           ordered unit-price ops
//   machine | machine_override                                  descriptor w/ engine fields
//   customer_tier                                               line-scoped tier pin
//   tier_rules | tierRules | tier_matrix | templates |
//     pricing_templates | tiers                                 line-embedded registries
//   pricing | price_config | engine_pricing | pricing_config |
//     engine_price                                              nested config block
//
// Descriptor merge per line (weakest -> strongest):
//   flat item fields  <-  project engine_pricing.items[<line key>]  <-
//   item.pricing | .price_config | .engine_pricing | .pricing_config |
//   .engine_price nested block.
//
// Project-level context carrier (record.engine_pricing / .pricing_context /
// .engine_context / .pricing_engine — tolerated extras):
//   customer_tier, tier_rules | tierRules | tier_matrix, templates,
//   tiers | tier_catalog, default_markup_pct | defaultMarkupPct, now,
//   items | lines: { <item builder_item_id|id|key|index>: <part descriptor> }.
// Caller-supplied `context` always outranks the record-embedded block; the
// record's saved Markup-Tier snapshot (customer_pricing.tier_number) is the
// weakest customer-tier source.
//
// Cost-base rule (safety): only lines with a finite numeric cost base can be
// engine-priced — the wire must subtract exactly the baseline sell it
// replaces. Laser spells it two ways: a single-total field (item_total_cost |
// line_total_cost | total_cost | extended_cost | line_cost | item_cost |
// cost | computed_cost — calcLaserProject's item_total_cost first) or the
// persisted machine_cost + labor_cost component pair written by
// LaserEstimator's calculateTotals. A configured line without a cost base is
// SKIPPED (skipped_no_cost warning, baseline untouched) rather than
// double-charging or zeroing sell dollars.
//
// qty: item.quantity | qty | count, default 1 — 0 is honored (extension 0,
// engine minimum never fires on extension <= 0). unitCost = lineCost/qty for
// qty > 0 else the raw lineCost. The whole pipeline never throws; every
// resolution step is echoed in `chain` for transparency.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/**
 * Line cost-base spellings (single-total fields; calcLaserProject's
 * item_total_cost first). When none is present the wire falls back to the
 * persisted machine_cost + labor_cost component pair — the shape
 * LaserEstimator.jsx actually saves on each item.
 */
const LINE_COST_FIELDS = [
  'item_total_cost', 'line_total_cost', 'total_cost', 'extended_cost',
  'line_cost', 'item_cost', 'cost', 'computed_cost',
] as const;

/** Laser cost components persisted per item by the estimator page. */
const LINE_COST_COMPONENT_FIELDS = ['machine_cost', 'labor_cost'] as const;

const LINE_QTY_FIELDS = ['quantity', 'qty', 'count'] as const;

const LINE_LABEL_FIELDS = ['description', 'label', 'name', 'item_name', 'part_name'] as const;

/** builder_item_id is the stable hidden row identity seeded by the page. */
const LINE_KEY_FIELDS = ['builder_item_id', 'id', 'item_id', 'part_id', 'key', 'line_id'] as const;

/** item_type (panel|lettering|engraving|engrave_and_cut) doubles as the pricing category. */
const LINE_CATEGORY_FIELDS = ['category_key', 'category', 'part_category', 'pricing_category', 'item_type'] as const;

/** Project record blocks that may carry engine context + per-line overrides. */
const ENGINE_BLOCK_FIELDS = ['engine_pricing', 'pricing_context', 'engine_context', 'pricing_engine'] as const;

/** Nested per-item config blocks. */
const NESTED_CONFIG_FIELDS = ['pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price'] as const;

/** Map inside the project block keyed by line key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Pricing-mode tokens that count as engine config (unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog'] as const;

/**
 * Flat item fields the engine can read — copied into the line descriptor.
 * (Field names only; presence does not by itself mark the line configured —
 * see descriptorHasPricingContent.)
 */
export const LASER_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  'unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a laser unit/type enum (pricing_mode
 * 'per_hour', item_type 'panel'|'engraving', material_type 'Acrylic') or a
 * bare machine name must NOT flip the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// laser record -> normalized lines
// ---------------------------------------------------------------------------

export interface LaserWireLine {
  /** Stable key — builder_item_id, else item id, else positional tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored). null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The raw laser item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'caller' = input.lines override. */
  origin: 'items' | 'caller';
}

const lineKey = (item: Record<string, unknown>, index: number): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return `idx-${index}`;
};

/**
 * The line's module-authored cost base: a persisted single-total field first
 * (calcLaserProject's item_total_cost), else the machine_cost + labor_cost
 * component pair LaserEstimator writes per item, else null (no cost base).
 */
const lineCostOf = (item: Record<string, unknown>): number | null => {
  const direct = firstFinite(item, LINE_COST_FIELDS);
  if (direct !== null) return direct;
  const machine = toFiniteNumber(item.machine_cost);
  const labor = toFiniteNumber(item.labor_cost);
  if (machine === null && labor === null) return null;
  return num(machine) + num(labor);
};

/**
 * Normalize a LaserProject-like record to the wire's line list. The persisted
 * flat `record.items` list is the only line source — the module has no
 * nested workflow structures.
 */
export function laserRecordLines(record: unknown): LaserWireLine[] {
  if (!isRecord(record)) return [];
  const flat = Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : [];
  return flat.map((item, index) => ({
    key: lineKey(item, index),
    index,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || `Item ${index + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: lineCostOf(item),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin: 'items' as const,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface LaserPricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (absent on laser records today, so 0 — a configured-but-
 * unresolved line then naturally lands on its own cost baseline).
 */
export function laserPricingContextOf(record: unknown, callerContext: unknown = null): LaserPricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function laserLineDescriptor(line: LaserWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as LaserWireLine)?.item)
    ? (line as LaserWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of LASER_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as LaserWireLine)?.key]) ? lineMap[(line as LaserWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as LaserWireLine)?.index)]) ? lineMap[asString((line as LaserWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface LaserConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which laser lines carry pricing-engine config. Cheap and
 * side-effect free; callers may use it to decide whether engine resolution is
 * needed at all.
 */
export function laserConfigScan(record: unknown, lines?: LaserWireLine[]): LaserConfigScan {
  const wireLines = Array.isArray(lines) ? lines : laserRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = laserLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolveLaserSellPricing
// ---------------------------------------------------------------------------

export interface LaserWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface LaserSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface LaserSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: LaserSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: LaserSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: LaserSellLineResult[],
  chain: LaserSellPricingResult['chain'],
  warnings: string[],
  contextUsed: LaserSellPricingResult['context_used'],
): LaserSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the laser project sell price through the injected pricing engine.
 *
 * input.record          LaserProject-like (items[])
 * input.lines           optional explicit LaserWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.total_cost), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal, else 0 (laser today)
 * input.context         laserPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveLaserSellPricing(input: any = {}): LaserSellPricingResult {
  const warnings: string[] = [];
  const chain: LaserSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = laserPricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: LaserWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: LaserWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : laserRecordLines(rec);

  const scan = laserConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: LaserSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = laserLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : lineCostOf(rawItem);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: LaserSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Metal module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23f) — pure TS,
// ZERO imports, NO IO. Bundles clean for Deno base44 functions and the Vite
// frontend (frontend-shared-modules allowlist).
//
// What this does: the metal module's COST math stays authoritative — the
// persisted per-item material_cost / supplies_cost / fabrication_cost /
// welding_cost / finishing_cost components written by MetalEstimator.jsx
// updateItem are PER-UNIT dollars, and the page extends them with
// (quantity || 1) when it builds the project totals (calculateTotals /
// getProjectCalculations -> total_material_cost..total_finishing_cost ->
// total_cost). The estimator/metal/metalCalc.js calcMetalProject shape
// (extended components + item_total_cost, project-level markup_percent) is
// tolerated too. This wire only re-prices the SELL side of metal lines that
// carry a pricing-tier/template config. The engine is INJECTED by the caller
// ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ZERO-REGRESSION CONTRACT: a metal record whose lines carry no engine-vocab
// pricing config resolves { applied:false, passthrough:true,
// customer_price === baselineSell } — the caller returns the module's own
// sell price verbatim (byte-identical at the customerPricing seam). Today's
// page-saved metal records carry no module markup (subtotal === total_cost,
// markup_amount/markup_percent persist 0 — the saved customer_pricing
// Markup-Tier snapshot is a separate layer), so on canonical records the
// module markup factor is 1 and each configured line's baseline contribution
// is exactly its own extended line cost. metalCalc-style records that do
// persist a markup keep it honored linearly per line:
//
//   remainder      = baselineSell - Σ configured line cost × (1+markupPct/100)
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
//
// Because the remainder only subtracts configured lines' extended costs,
// everything not repriced — un-configured lines, extra_supplies_cost, and
// any other project-level dollars inside total_cost — keeps its exact
// baseline contribution.
//
// ---------------------------------------------------------------------------
// Activation contract — "a line carrying a pricing-tier config"
// ---------------------------------------------------------------------------
// A metal line (record.items[] row — the persisted flat list) is engine-priced
// when its resolved descriptor carries at least one pricing-engine field:
//
//   fixed_price | price_override | override_price | flat_price   pinned unit sell
//   tier_ref | tier_ref_id | tier | tier_name | pricing_tier_ref  bound tier row
//   per_unit_breaks | unit_breaks | qty_breaks                    qty chart
//   pricing_template_id | template_id | margin_template_id |
//     pricing_template_name | template_name | pricing_template | template
//                                                              bound PricingTemplate
//   global_pricing_tier_id | pricing_tier_id | tier_set_id |
//     pricing_tier_set_id | pricing_rule_set_id | global_tier_id |
//     global_pricing_tier_name | pricing_tier_name | tier_set_name
//                                                              bound GlobalPricingTier
//   market_retail | retail | retail_price | list_price |
//     market_discount_pct | retail_discount_pct                 market-based pricing
//   pricing_mode | price_mode | mode   (engine tokens 'market' | 'market_based'
//     | 'market-based' | 'retail' | 'retail_minus_discount' | 'fixed' |
//     'fixed_price' | 'flat' ONLY — metal unit/type enums like 'per_piece' /
//     'per_pound' / 'per_sqft' / 'per_foot' (Inventory.unit_type) and the
//     item_type enum ('channel_letters' | 'cabinet_sign' | 'monument_sign' |
//     'pole_sign' | 'flat_cut_letters' | 'fabricated_letters' |
//     'frame_assembly' | 'custom_brackets') are NOT pricing config;
//     material_length_ft / fabrication_hours / welding_hours /
//     finishing_hours / the per-unit cost components / rates /
//     dimensions_display / labor_hours are cost-side fields and are never
//     config)
//   markup_pct | markup | markup_percent                        part markup
//   minimum_charge | min_charge | minimum | setup_fee_floor     extension floor
//   setup_fee | setupFee | setup_fee_flat                       flat sell fee
//   formula_modifiers                                           ordered unit-price ops
//   machine | machine_override                                  descriptor w/ engine fields
//   customer_tier                                               line-scoped tier pin
//   tier_rules | tierRules | tier_matrix | templates |
//     pricing_templates | tiers                                 line-embedded registries
//   pricing | price_config | engine_pricing | pricing_config |
//     engine_price                                              nested config block
//
// Descriptor merge per line (weakest -> strongest):
//   flat item fields  <-  project engine_pricing.items[<line key>]  <-
//   item.pricing | .price_config | .engine_pricing | .pricing_config |
//   .engine_price nested block.
//
// Project-level context carrier (record.engine_pricing / .pricing_context /
// .engine_context / .pricing_engine — tolerated extras):
//   customer_tier, tier_rules | tierRules | tier_matrix, templates,
//   tiers | tier_catalog, default_markup_pct | defaultMarkupPct, now,
//   items | lines: { <item builder_item_id|id|key|index>: <part descriptor> }.
// Caller-supplied `context` always outranks the record-embedded block; the
// record's saved Markup-Tier snapshot (customer_pricing.tier_number) is the
// weakest customer-tier source.
//
// Cost-base rule (safety): only lines with a finite numeric cost base can be
// engine-priced — the wire must subtract exactly the baseline sell it
// replaces. Metal spells the line cost three ways:
//   a. a single-total field (item_total_cost | line_total_cost | total_cost |
//      extended_cost | line_cost | item_cost | cost | computed_cost —
//      calcMetalProject's item_total_cost first) — taken as EXTENDED;
//   b. the page's display-enrichment spellings (materials_cost + labor_cost,
//      with supplies_cost rewritten extended) — taken as EXTENDED when either
//      enriched field is finite;
//   c. the canonical persisted PER-UNIT component set
//      (material_cost + supplies_cost + fabrication_cost + welding_cost +
//      finishing_cost) — extended with the page's own (quantity || 1)
//      multiplier so a persisted qty of 0 keeps the page's ×1 cost semantics.
//      When a record's component dollars are instead already extended (a
//      foreign/imported writer), metalComponentsAreExtended() compares both
//      interpretations against the record's own total_*_cost fields /
//      subtotal and picks the closer one — canonical per-unit wins ties and
//      the no-evidence default.
// A configured line without a cost base is SKIPPED (skipped_no_cost warning,
// baseline untouched) rather than double-charging or zeroing sell dollars.
//
// qty: item.quantity | qty | count, default 1 — 0 is honored for the engine
// extension (engine minimum never fires on extension <= 0) even though the
// page's baseline math uses (quantity || 1). unitCost = lineCost/qty for
// qty > 0 else the raw lineCost. The whole pipeline never throws; every
// resolution step is echoed in `chain` for transparency.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/**
 * Line cost-base spellings — single-total fields taken as already EXTENDED
 * (calcMetalProject's item_total_cost first).
 */
const LINE_COST_FIELDS = [
  'item_total_cost', 'line_total_cost', 'total_cost', 'extended_cost',
  'line_cost', 'item_cost', 'cost', 'computed_cost',
] as const;

/**
 * Canonical persisted cost components — MetalEstimator.jsx writes these
 * PER-UNIT (material_cost = material_length_ft × inventory cost_per_unit;
 * *_cost = *_hours × *_rate) and the page multiplies each by
 * (item.quantity || 1) when building the project totals.
 */
const LINE_COMPONENT_FIELDS = [
  'material_cost', 'supplies_cost', 'fabrication_cost', 'welding_cost', 'finishing_cost',
] as const;

/** Persisted project totals matching LINE_COMPONENT_FIELDS 1:1. */
const RECORD_COMPONENT_TOTAL_FIELDS = [
  'total_material_cost', 'total_supplies_cost', 'total_fabrication_cost',
  'total_welding_cost', 'total_finishing_cost',
] as const;

/**
 * Display-enrichment spellings (getProjectCalculations' enrichedItems):
 * materials_cost + labor_cost arrive already EXTENDED and supplies_cost is
 * rewritten extended alongside them — detected by either enriched field
 * being finite so the canonical per-unit row never misfires on supplies.
 */
const ENRICHED_MATERIAL_FIELDS = ['materials_cost'] as const;
const ENRICHED_LABOR_FIELDS = ['labor_cost'] as const;

const LINE_QTY_FIELDS = ['quantity', 'qty', 'count'] as const;

const LINE_LABEL_FIELDS = ['description', 'label', 'name', 'item_name', 'part_name'] as const;

/** builder_item_id is the stable hidden row identity seeded by the page. */
const LINE_KEY_FIELDS = ['builder_item_id', 'id', 'item_id', 'part_id', 'key', 'line_id'] as const;

/** item_type (channel_letters|cabinet_sign|monument_sign|pole_sign|flat_cut_letters|fabricated_letters|frame_assembly|custom_brackets) doubles as the pricing category. */
const LINE_CATEGORY_FIELDS = ['category_key', 'category', 'part_category', 'pricing_category', 'item_type'] as const;

/** Project record blocks that may carry engine context + per-line overrides. */
const ENGINE_BLOCK_FIELDS = ['engine_pricing', 'pricing_context', 'engine_context', 'pricing_engine'] as const;

/** Nested per-item config blocks. */
const NESTED_CONFIG_FIELDS = ['pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price'] as const;

/** Map inside the project block keyed by line key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Pricing-mode tokens that count as engine config (unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog'] as const;

/**
 * Flat item fields the engine can read — copied into the line descriptor.
 * (Field names only; presence does not by itself mark the line configured —
 * see descriptorHasPricingContent.)
 */
export const METAL_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  'unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a metal unit/type enum (pricing_mode
 * 'per_piece', item_type 'cabinet_sign', Inventory unit_type 'per_foot') or a
 * bare machine name must NOT flip the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// metal record -> normalized lines
// ---------------------------------------------------------------------------

export interface MetalWireLine {
  /** Stable key — builder_item_id, else item id, else positional tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored). null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The raw metal item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'caller' = input.lines override. */
  origin: 'items' | 'caller';
}

const lineKey = (item: Record<string, unknown>, index: number): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return `idx-${index}`;
};

/** The page's own quantity multiplier: (item.quantity || 1). */
const qtyMultiplier = (item: Record<string, unknown>): number =>
  num(firstField(item, LINE_QTY_FIELDS), 1) || 1;

/** Does this item carry the page's enriched extended-cost spellings? */
const hasEnrichedCost = (item: Record<string, unknown>): boolean =>
  firstFinite(item, ENRICHED_MATERIAL_FIELDS) !== null
  || firstFinite(item, ENRICHED_LABOR_FIELDS) !== null;

/**
 * Does this item's cost base come from the canonical per-unit component set?
 * (No single-total field and no enriched markers.) Only those items
 * participate in the record-level component-interpretation check.
 */
const isComponentCostItem = (item: Record<string, unknown>): boolean =>
  firstFinite(item, LINE_COST_FIELDS) === null
  && !hasEnrichedCost(item)
  && LINE_COMPONENT_FIELDS.some((f) => toFiniteNumber(item[f]) !== null);

/**
 * Record-level disambiguation for the canonical component set: are the
 * persisted component dollars PER-UNIT (the page's shape — extended with
 * qty||1) or already EXTENDED (a foreign writer)? The record's own
 * total_*_cost fields are the ground truth — they were computed with the
 * same interpretation the writer used. Sum both candidate interpretations
 * per component and pick the globally closer one; when no component totals
 * exist, compare Σ line totals against record.subtotal /
 * total_cost - markup_amount the same way. Canonical per-unit wins ties and
 * the no-evidence default.
 */
export function metalComponentsAreExtended(record: unknown, items?: Record<string, unknown>[]): boolean {
  const rec = isRecord(record) ? record : {};
  const list = Array.isArray(items)
    ? items
    : (Array.isArray(rec.items) ? (rec.items as unknown[]).filter(isRecord) : []);
  const componentItems = list.filter(isComponentCostItem);
  if (!componentItems.length) return false;

  let errExtended = 0;
  let errPerUnit = 0;
  let compared = 0;

  LINE_COMPONENT_FIELDS.forEach((comp, i) => {
    const recorded = toFiniteNumber(rec[RECORD_COMPONENT_TOTAL_FIELDS[i]]);
    if (recorded === null) return;
    let sumExtended = 0;
    let sumPerUnit = 0;
    let any = false;
    for (const item of componentItems) {
      const v = toFiniteNumber(item[comp]);
      if (v === null) continue;
      any = true;
      sumExtended += v;
      sumPerUnit += v * qtyMultiplier(item);
    }
    if (!any) return;
    errExtended += Math.abs(sumExtended - recorded);
    errPerUnit += Math.abs(sumPerUnit - recorded);
    compared += 1;
  });

  if (!compared) {
    // No persisted component totals — fall back to the project cost basis
    // (subtotal, else total_cost net of the markup layer) vs Σ line totals.
    // Lines whose cost does not come from the component set (single-total /
    // enriched spellings) are interpretation-independent — they add their
    // resolved cost to BOTH candidate sums so the comparison stays fair.
    const basis = firstFinite(rec, ['subtotal'])
      ?? (toFiniteNumber(rec.total_cost) !== null
        ? num(rec.total_cost) - num(rec.markup_amount)
        : null);
    if (basis === null) return false;
    let sumExtended = 0;
    let sumPerUnit = 0;
    for (const item of list) {
      if (isComponentCostItem(item)) {
        const comps = LINE_COMPONENT_FIELDS.reduce((s, f) => s + num(item[f]), 0);
        sumExtended += comps;
        sumPerUnit += comps * qtyMultiplier(item);
      } else {
        const other = lineCostOf(item, false);
        if (other === null) continue;
        sumExtended += other;
        sumPerUnit += other;
      }
    }
    errExtended = Math.abs(sumExtended - basis);
    errPerUnit = Math.abs(sumPerUnit - basis);
  }

  return errExtended < errPerUnit;
}

/**
 * The line's module-authored EXTENDED cost base: a persisted single-total
 * field first (calcMetalProject's item_total_cost), else the enriched
 * materials_cost + supplies_cost + labor_cost triple the page builds for
 * display, else the canonical per-unit component set extended with the
 * record-appropriate interpretation. null = no cost base.
 */
const lineCostOf = (item: Record<string, unknown>, componentsExtended = false): number | null => {
  const direct = firstFinite(item, LINE_COST_FIELDS);
  if (direct !== null) return direct;

  if (hasEnrichedCost(item)) {
    return num(firstFinite(item, ENRICHED_MATERIAL_FIELDS))
      + num(item.supplies_cost)
      + num(firstFinite(item, ENRICHED_LABOR_FIELDS));
  }

  const hasComponent = LINE_COMPONENT_FIELDS.some((f) => toFiniteNumber(item[f]) !== null);
  if (!hasComponent) return null;
  const compSum = LINE_COMPONENT_FIELDS.reduce((s, f) => s + num(item[f]), 0);
  return componentsExtended ? compSum : compSum * qtyMultiplier(item);
};

/**
 * Normalize a MetalProject-like record to the wire's line list. The persisted
 * flat `record.items` list is the only line source — the module has no
 * nested workflow structures.
 */
export function metalRecordLines(record: unknown): MetalWireLine[] {
  if (!isRecord(record)) return [];
  const flat = (Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : []) as Record<string, unknown>[];
  const componentsExtended = metalComponentsAreExtended(record, flat);
  return flat.map((item, index) => ({
    key: lineKey(item, index),
    index,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || `Item ${index + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: lineCostOf(item, componentsExtended),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin: 'items' as const,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface MetalPricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (0 on today's page-saved records — a configured-but-
 * unresolved line then naturally lands on its own cost baseline).
 */
export function metalPricingContextOf(record: unknown, callerContext: unknown = null): MetalPricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function metalLineDescriptor(line: MetalWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as MetalWireLine)?.item)
    ? (line as MetalWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of METAL_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as MetalWireLine)?.key]) ? lineMap[(line as MetalWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as MetalWireLine)?.index)]) ? lineMap[asString((line as MetalWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface MetalConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which metal lines carry pricing-engine config. Cheap and
 * side-effect free; callers may use it to decide whether engine resolution is
 * needed at all.
 */
export function metalConfigScan(record: unknown, lines?: MetalWireLine[]): MetalConfigScan {
  const wireLines = Array.isArray(lines) ? lines : metalRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = metalLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolveMetalSellPricing
// ---------------------------------------------------------------------------

export interface MetalWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface MetalSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface MetalSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: MetalSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: MetalSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: MetalSellLineResult[],
  chain: MetalSellPricingResult['chain'],
  warnings: string[],
  contextUsed: MetalSellPricingResult['context_used'],
): MetalSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the metal project sell price through the injected pricing engine.
 *
 * input.record          MetalProject-like (items[])
 * input.lines           optional explicit MetalWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.subtotal /
 *                       total_cost - markup_amount), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal, else 0 (page-saved metal)
 * input.context         metalPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveMetalSellPricing(input: any = {}): MetalSellPricingResult {
  const warnings: string[] = [];
  const chain: MetalSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = metalPricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: MetalWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: MetalWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : metalRecordLines(rec);

  const scan = metalConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: MetalSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;
  // input.lines rows may arrive raw (not yet folded by metalRecordLines) —
  // decide the component interpretation once against the record's totals.
  const componentsExtended = metalComponentsAreExtended(rec);

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = metalLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : lineCostOf(rawItem, componentsExtended);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: MetalSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Painting module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23g) — pure TS,
// ZERO imports, NO IO. Bundles clean for Deno base44 functions and the Vite
// frontend (frontend-shared-modules allowlist).
//
// What this does: the painting module's COST math stays authoritative — the
// persisted per-item supplies_cost (paint mask) / paint_cost (liquid paint +
// application supplies) / labor_cost components written by
// PaintingEstimator.jsx are already EXTENDED dollars
// (estimator/paint/paintCalc.js calculatePaintingItem multiplies the mask and
// paint components by qty, and labor_cost = discounted hours x rate x qty).
// The project-level fixed dollars — global fixed-waste paint inside
// record.total_liquid_paint_and_supplies_cost, mixing/setup/color-change/
// gun-cleaning labor and the min-labor / min-paint floors inside
// record.total_labor_cost — live in the three record component totals but not
// in any line. This wire only re-prices the SELL side of paint lines that
// carry a pricing-tier/template config. The engine is INJECTED by the caller
// ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ZERO-REGRESSION CONTRACT: a painting record whose lines carry no
// engine-vocab pricing config resolves { applied:false, passthrough:true,
// customer_price === baselineSell } — the caller returns the module's own
// sell price verbatim (byte-identical at the customerPricing seam). Painting
// records carry no module markup (the baseline sell IS the pure cost sum —
// sourceProjectTotal's painting branch returns total_paint_mask_cost +
// total_liquid_paint_and_supplies_cost + total_labor_cost; record.total_cost
// is absent — and the saved customer_pricing Markup-Tier snapshot is a
// separate layer), so the module markup factor is 1 and each configured
// line's baseline contribution is exactly its own extended line cost:
//
//   remainder      = baselineSell - Σ configured line cost
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
//
// Because the remainder only subtracts configured lines' costs, everything
// not repriced — un-configured lines, the global fixed-waste dollars, the
// fixed labor (mixing/setup/color-change/gun-cleaning) and any min-floor
// adjustment inside the record totals — keeps its exact baseline
// contribution. markupPct still honors input.markupPercent /
// record.markup_percent / markup_amount÷subtotal for forward parity with the
// other module wires; on today's paint records it resolves to 0.
//
// ---------------------------------------------------------------------------
// Activation contract — "a line carrying a pricing-tier config"
// ---------------------------------------------------------------------------
// A paint line (record.items[] row — the persisted flat list) is
// engine-priced when its resolved descriptor carries at least one
// pricing-engine field:
//
//   fixed_price | price_override | override_price | flat_price   pinned unit sell
//   tier_ref | tier_ref_id | tier | tier_name | pricing_tier_ref  bound tier row
//   per_unit_breaks | unit_breaks | qty_breaks                    qty chart
//   pricing_template_id | template_id | margin_template_id |
//     pricing_template_name | template_name | pricing_template | template
//                                                              bound PricingTemplate
//   global_pricing_tier_id | pricing_tier_id | tier_set_id |
//     pricing_tier_set_id | pricing_rule_set_id | global_tier_id |
//     global_pricing_tier_name | pricing_tier_name | tier_set_name
//                                                              bound GlobalPricingTier
//   market_retail | retail | retail_price | list_price |
//     market_discount_pct | retail_discount_pct                 market-based pricing
//   pricing_mode | price_mode | mode   (engine tokens 'market' | 'market_based'
//     | 'market-based' | 'retail' | 'retail_minus_discount' | 'fixed' |
//     'fixed_price' | 'flat' ONLY — paint unit/type enums like
//     item_type 'panel' | 'lettering' | 'complex_shapes', paint_sides
//     'one_side' | 'both_sides', the letter_size enum and thickness
//     fractions are NOT pricing config; paint_mask_sqft /
//     base_supplies_cost / fixed_waste_gallons / supplies_cost / paint_cost /
//     paint_gallons / labor_hours / labor_cost / paintable_sqft /
//     paint_colors / edge_complexity_multiplier / length / width are
//     cost-side fields and are never config)
//   markup_pct | markup | markup_percent                        part markup
//   minimum_charge | min_charge | minimum | setup_fee_floor     extension floor
//   setup_fee | setupFee | setup_fee_flat                       flat sell fee
//   formula_modifiers                                           ordered unit-price ops
//   machine | machine_override                                  descriptor w/ engine fields
//   customer_tier                                               line-scoped tier pin
//   tier_rules | tierRules | tier_matrix | templates |
//     pricing_templates | tiers                                 line-embedded registries
//   pricing | price_config | engine_pricing | pricing_config |
//     engine_price                                              nested config block
//
// Descriptor merge per line (weakest -> strongest):
//   flat item fields  <-  project engine_pricing.items[<line key>]  <-
//   item.pricing | .price_config | .engine_pricing | .pricing_config |
//   .engine_price nested block.
//
// Project-level context carrier (record.engine_pricing / .pricing_context /
// .engine_context / .pricing_engine — tolerated extras):
//   customer_tier, tier_rules | tierRules | tier_matrix, templates,
//   tiers | tier_catalog, default_markup_pct | defaultMarkupPct, now,
//   items | lines: { <item builder_item_id|id|key|index>: <part descriptor> }.
// Caller-supplied `context` always outranks the record-embedded block; the
// record's saved Markup-Tier snapshot (customer_pricing.tier_number) is the
// weakest customer-tier source.
//
// Cost-base rule (safety): only lines with a finite numeric cost base can be
// engine-priced — the wire must subtract exactly the baseline sell it
// replaces. Paint spells the line cost two ways:
//   a. a single-total field (item_total_cost | line_total_cost | total_cost |
//      extended_cost | line_cost | item_cost | cost | computed_cost) —
//      taken as EXTENDED;
//   b. the canonical persisted EXTENDED component triple
//      (supplies_cost + paint_cost + labor_cost) — already multiplied
//      through qty by calculatePaintingItem.
//      When a record's component dollars are instead already PER-UNIT (a
//      foreign/imported writer), paintComponentsAreExtended() arbitrates
//      against the record's own total_paint_mask_cost — the ONE component
//      total with no project-level extras (it is exactly Σ item
//      supplies_cost under either interpretation) — and picks the closer
//      reading. The liquid-paint and labor totals are NOT arbitrators: both
//      fold in unknown fixed extras (global waste, fixed labor, min floors)
//      that could falsely crown the per-unit reading on small jobs.
//      Canonical extended wins the no-evidence default.
// A configured line without a cost base is SKIPPED (skipped_no_cost warning,
// baseline untouched) rather than double-charging or zeroing sell dollars.
//
// qty: item.quantity | qty | count, default 1 — 0 is honored for the engine
// extension (engine minimum never fires on extension <= 0) even though the
// page's baseline math pins lettering items to qty 1 (letter height/count
// are already folded into the persisted paint geometry). unitCost =
// lineCost/qty for qty > 0 else the raw lineCost. The whole pipeline never
// throws; every resolution step is echoed in `chain` for transparency.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/**
 * Line cost-base spellings — single-total fields taken as already EXTENDED
 * (a foreign single-total writer's item_total_cost first).
 */
const LINE_COST_FIELDS = [
  'item_total_cost', 'line_total_cost', 'total_cost', 'extended_cost',
  'line_cost', 'item_cost', 'cost', 'computed_cost',
] as const;

/**
 * Canonical persisted cost components — PaintingEstimator.jsx saves the
 * calculatePaintingItem output per item where supplies_cost (paint mask) and
 * paint_cost (liquid paint + application supplies) are component x qty and
 * labor_cost is already extended (discounted hours x rate x qty).
 */
const LINE_COMPONENT_FIELDS = ['supplies_cost', 'paint_cost', 'labor_cost'] as const;

const LINE_QTY_FIELDS = ['quantity', 'qty', 'count'] as const;

const LINE_LABEL_FIELDS = ['description', 'label', 'name', 'item_name', 'part_name'] as const;

/** builder_item_id is the stable hidden row identity seeded by the page. */
const LINE_KEY_FIELDS = ['builder_item_id', 'id', 'item_id', 'part_id', 'key', 'line_id'] as const;

/** item_type (panel|lettering|complex_shapes) doubles as the pricing category. */
const LINE_CATEGORY_FIELDS = ['category_key', 'category', 'part_category', 'pricing_category', 'item_type'] as const;

/** Project record blocks that may carry engine context + per-line overrides. */
const ENGINE_BLOCK_FIELDS = ['engine_pricing', 'pricing_context', 'engine_context', 'pricing_engine'] as const;

/** Nested per-item config blocks. */
const NESTED_CONFIG_FIELDS = ['pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price'] as const;

/** Map inside the project block keyed by line key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Pricing-mode tokens that count as engine config (unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog'] as const;

/**
 * Flat item fields the engine can read — copied into the line descriptor.
 * (Field names only; presence does not by itself mark the line configured —
 * see descriptorHasPricingContent.)
 */
export const PAINT_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  'unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a paint unit/type enum (pricing_mode
 * 'per_sqft', item_type 'panel', paint_sides 'both_sides') or a bare machine
 * name must NOT flip the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// paint record -> normalized lines
// ---------------------------------------------------------------------------

export interface PaintWireLine {
  /** Stable key — builder_item_id, else item id, else positional tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored). null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The raw paint item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'caller' = input.lines override. */
  origin: 'items' | 'caller';
}

const lineKey = (item: Record<string, unknown>, index: number): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return `idx-${index}`;
};

/** The page's own quantity multiplier: max(quantity || 1, 1). */
const qtyMultiplier = (item: Record<string, unknown>): number =>
  Math.max(num(firstField(item, LINE_QTY_FIELDS), 1) || 1, 1);

/** Does this item's cost base come from the canonical component triple? */
const isComponentCostItem = (item: Record<string, unknown>): boolean =>
  firstFinite(item, LINE_COST_FIELDS) === null
  && LINE_COMPONENT_FIELDS.some((f) => toFiniteNumber(item[f]) !== null);

/**
 * Record-level disambiguation for the canonical component triple: are the
 * persisted component dollars EXTENDED (the page's shape — the only
 * interpretation PaintingEstimator writes) or PER-UNIT (a foreign writer
 * that extends with qty itself when building the record totals)?
 *
 * Only total_paint_mask_cost can arbitrate: it is exactly Σ item
 * supplies_cost with NO project-level extras, so under whichever
 * interpretation the writer used one candidate sum lands on it dead-on.
 * The liquid-paint and labor totals fold in unknown extras (global fixed
 * waste dollars, mixing/setup/color-change/gun-cleaning labor, min floors)
 * that could falsely crown the per-unit reading on small jobs — they are
 * deliberately not consulted. Canonical extended wins the no-evidence
 * default and ties.
 */
export function paintComponentsAreExtended(record: unknown, items?: Record<string, unknown>[]): boolean {
  const rec = isRecord(record) ? record : {};
  const list = Array.isArray(items)
    ? items
    : (Array.isArray(rec.items) ? (rec.items as unknown[]).filter(isRecord) : []);
  const componentItems = list.filter(isComponentCostItem);
  if (!componentItems.length) return true;

  const recordedMask = toFiniteNumber(rec.total_paint_mask_cost);
  if (recordedMask === null) return true;

  let any = false;
  let sumExtended = 0;
  let sumPerUnit = 0;
  for (const item of componentItems) {
    const v = toFiniteNumber(item.supplies_cost);
    if (v === null) continue;
    any = true;
    sumExtended += v;
    sumPerUnit += v * qtyMultiplier(item);
  }
  // Interpretations agree (all qty 1 / all-zero supplies) — no evidence.
  if (!any || Math.abs(sumExtended - sumPerUnit) <= 0.005) return true;

  return Math.abs(sumExtended - recordedMask) <= Math.abs(sumPerUnit - recordedMask);
}

/**
 * The line's module-authored EXTENDED cost base: a persisted single-total
 * field first, else the canonical supplies_cost + paint_cost + labor_cost
 * triple under the record-appropriate interpretation.
 * null = no cost base.
 */
const lineCostOf = (item: Record<string, unknown>, componentsExtended = true): number | null => {
  const direct = firstFinite(item, LINE_COST_FIELDS);
  if (direct !== null) return direct;

  const hasComponent = LINE_COMPONENT_FIELDS.some((f) => toFiniteNumber(item[f]) !== null);
  if (!hasComponent) return null;
  const compSum = LINE_COMPONENT_FIELDS.reduce((s, f) => s + num(item[f]), 0);
  return componentsExtended ? compSum : compSum * qtyMultiplier(item);
};

/**
 * Normalize a paint Project-like record to the wire's line list. The
 * persisted flat `record.items` list is the only line source — the module
 * has no nested workflow structures.
 */
export function paintRecordLines(record: unknown): PaintWireLine[] {
  if (!isRecord(record)) return [];
  const flat = (Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : []) as Record<string, unknown>[];
  const componentsExtended = paintComponentsAreExtended(record, flat);
  return flat.map((item, index) => ({
    key: lineKey(item, index),
    index,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || `Item ${index + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: lineCostOf(item, componentsExtended),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin: 'items' as const,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface PaintPricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (absent on paint records today, so 0 — a configured-but-
 * unresolved line then naturally lands on its own cost baseline).
 */
export function paintPricingContextOf(record: unknown, callerContext: unknown = null): PaintPricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function paintLineDescriptor(line: PaintWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as PaintWireLine)?.item)
    ? (line as PaintWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of PAINT_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as PaintWireLine)?.key]) ? lineMap[(line as PaintWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as PaintWireLine)?.index)]) ? lineMap[asString((line as PaintWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface PaintConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which paint lines carry pricing-engine config. Cheap and
 * side-effect free; callers may use it to decide whether engine resolution is
 * needed at all.
 */
export function paintConfigScan(record: unknown, lines?: PaintWireLine[]): PaintConfigScan {
  const wireLines = Array.isArray(lines) ? lines : paintRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = paintLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolvePaintSellPricing
// ---------------------------------------------------------------------------

export interface PaintWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface PaintSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface PaintSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: PaintSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: PaintSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: PaintSellLineResult[],
  chain: PaintSellPricingResult['chain'],
  warnings: string[],
  contextUsed: PaintSellPricingResult['context_used'],
): PaintSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the paint project sell price through the injected pricing engine.
 *
 * input.record          paint Project-like (items[] + the three component
 *                       totals)
 * input.lines           optional explicit PaintWireLine[] override
 * input.baselineSell    the module's sell price today
 *                       (total_paint_mask_cost +
 *                       total_liquid_paint_and_supplies_cost +
 *                       total_labor_cost — sourceProjectTotal's painting
 *                       branch; record.total_cost is absent on paint rows) —
 *                       returned verbatim on every passthrough path
 * input.internalCost    module internal cost (same sum), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal, else 0 (paint today)
 * input.context         paintPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolvePaintSellPricing(input: any = {}): PaintSellPricingResult {
  const warnings: string[] = [];
  const chain: PaintSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = paintPricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: PaintWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: PaintWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : paintRecordLines(rec);

  const scan = paintConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: PaintSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = paintLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : lineCostOf(rawItem);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: PaintSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Foundation (Concrete | Masonry | Poles) pricing-engine wire
// (ESTIMATOR_MASTERPLAN F-23h) — pure TS, ZERO imports, NO IO. Bundles clean
// for Deno base44 functions and the Vite frontend (frontend-shared-modules
// allowlist).
//
// What this does: the foundation module's COST math (foundationCalc.js
// calcProject — per-item concrete/rebar/excavation/forming/pouring/finishing +
// concrete delivery + walls + poles + equipment + wall caps, rolled into
// totals.grand_total; FoundationEstimator.jsx additionally persists
// signage-cabinet and landscape totals) stays authoritative. This wire only
// re-prices the SELL side of foundation projects that carry an engine context
// block or component-scoped pricing config. The engine is INJECTED by the
// caller ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ---------------------------------------------------------------------------
// ZERO-REGRESSION CONTRACT
// ---------------------------------------------------------------------------
// A FoundationProject record carrying no engine-vocab config resolves
// { applied:false, passthrough:true, customer_price === baselineSell } — the
// caller returns the module's own sell price VERBATIM (byte-identical, no
// float ops, at the customerPricing.sourceProjectEconomics seam). The record's
// own cost/rate/geometry/sell fields (total_*_cost, grand_total, *_cost_per_*,
// *_labor_rate, customer_markup_percent, customer_price_override,
// concrete/rebar/forming rates, items[]/walls[]/poles[] inputs) are COST- or
// BASELINE-side inputs — they are never scanned for engine config (reading
// them would mark every saved record "configured": customer_markup_percent is
// the percent that produced the baseline tail, so it only feeds the engine as
// the DEFAULT markup, exactly like the brick wire's markup_percent). A legacy
// saved customer_pricing Markup-Tier snapshot alone never engages — it only
// feeds the context block as the weakest customer-tier hint.
//
// ---------------------------------------------------------------------------
// Entity contract — FoundationProject.jsonc (module key 'foundation')
// ---------------------------------------------------------------------------
//   items[]                 per-footing rows incl. persisted per-item costs
//   walls[]                 masonry walls w/ calculatedCosts{material,mortar,
//                           labor,internal*} snapshots
//   poles[] / wall_caps[] / signage_cabinets[] / selected_equipment[]
//   landscape {cells}       site-material grid (landscapeSummary)
//   total_concrete_cost     items' concrete + delivery (already includes
//                           concrete_delivery_cost)
//   total_rebar_cost / total_excavation_cost / total_forming_materials_cost
//   total_labor_cost        pouring + finishing labor
//   total_wall_cost         wall aggregate = material+mortar+labor+internal*
//   total_pole_cost / total_pole_painting_cost
//   total_equipment_cost / total_wall_cap_cost
//   total_signage_cabinet_cost / total_landscape_cost
//   customer_markup_percent / customer_price_override   module SELL inputs
//   customer_pricing {applied, tier_number, tier_name, total, lines[] — the
//   saved Markup-Tier snapshot; never carries engine_context/pricing_engine}
//
//   Sum invariant (builderService.sourceProjectTotal "known" fields — the
//   authoritative split-total partition when grand_total is absent, which it
//   always is on persisted records since payload() never writes it):
//     total_concrete + rebar + excavation + forming_materials + labor
//     + total_wall + pole + pole_painting + equipment + wall_cap
//     + signage_cabinet + landscape  ==  project cost total
//   total_brick_cost / total_fill_cost are SUBSETS of total_wall_cost (outer
//   material / internal fill only — no mortar, no labor) and are therefore
//   deliberately NOT component lines (they would double-count).
//
// Cost-line projection (foundationCostLines) — granular mirror of
// categorizeFoundationProject (projectCategorizer.jsx): the categorizer rolls
// concrete+rebar+forming into one outsourced_fab line, labor+excavation into
// inhouse_labor, poles+painting into outsourced_fab, and splits each wall's
// calculatedCosts into wall-material (outsourced_fab) vs wall-labor
// (outsourced_services); the wire keeps per-component granularity so
// component-scoped config prices on its own:
//   'concrete'      cost=total_concrete_cost        cat outsourced_fab
//   'rebar'         cost=total_rebar_cost           cat outsourced_fab
//   'excavation'    cost=total_excavation_cost      cat inhouse_labor
//   'forming'       cost=total_forming_materials_cost cat outsourced_fab
//   'labor'         cost=total_labor_cost           cat inhouse_labor
//   'wall_materials' Σwalls.material+mortar+internal* cat outsourced_fab
//   'wall_labor'    Σwalls.labor+internalLabor      cat outsourced_services
//   'walls'         cost=total_wall_cost (fallback when no walls[] breakdown)
//   'poles'         cost=total_pole_cost            cat outsourced_fab
//   'pole_painting' cost=total_pole_painting_cost   cat outsourced_fab
//   'equipment'     cost=total_equipment_cost       cat outsourced_services
//   'wall_caps'     cost=total_wall_cap_cost        cat outsourced_fab
//   'signage'       cost=total_signage_cabinet_cost cat outsourced_fab
//   'landscape'     cost=total_landscape_cost       cat outsourced_fab
// A component produces a line only when its cost field is FINITE (a present
// zero is a real line; absent/non-numeric drops the slot — a brand-new record
// with no computed costs yields no lines). qty honors an explicit 0
// (extension 0 — engine minimums never fire on extension <= 0, same as the
// brick wire); record-level qty fields win, else a row-derived sum
// (items[]/walls[]/poles[] counts and volumes), else 1 — which keeps markup
// math identical because unitCost*qty == cost either way.
//
// ---------------------------------------------------------------------------
// Activation contract — what counts as engine config on a foundation record
// ---------------------------------------------------------------------------
// 1. CONTEXT BLOCK (project-wide engagement — channel/brick parity):
//    record.pricing_engine | engine_pricing | pricing_tier_config |
//    pricing_context | engine_context, or
//    customer_pricing.engine_context | customer_pricing.pricing_engine.
//    Present-as-object => EVERY component line runs through the engine;
//    component descriptors override where present and unconfigured lines
//    price via the context chart / defaultMarkupPct (which defaults to
//    record.customer_markup_percent — the same percent that produced the
//    baseline tail, so an unconfigured line lands back on its own baseline).
// 2. COMPONENT-SCOPED LINE CONFIG (no context block): only the configured
//    component reprices; every other component keeps its exact baseline
//    contribution. Descriptor merge per line key K (weakest -> strongest):
//      a. flat prefixed record fields   `${K}_<engineField>`
//         (labor_markup_pct, concrete_fixed_price, poles_tier_ref,
//          equipment_market_retail, wall_materials_pricing_template_id, ...)
//      b. an inline descriptor carried on an explicit input.lines[] row
//      c. context-block line map        block.items|lines|line_config|
//                                       item_config[K] (numeric index ok)
//      d. nested component blocks       ${K}_pricing | ${K}_price_config |
//                                       ${K}_engine_pricing |
//                                       ${K}_pricing_config |
//                                       ${K}_engine_price |
//                                       ${K}_tier_config | ${K}_sell_pricing
//    Wall components answer to generic carriers too — 'walls'/'wall'
//    spellings (walls_pricing, walls_markup_pct, items.walls{...}) feed BOTH
//    wall_materials and wall_labor; the specific key wins where both exist.
//    A top-level record.pricing|part|... descriptor is deliberately NOT
//    scanned — a flat aggregate record has no unambiguous line owner for a
//    pinned unit price, and scanning raw record fields would trip on legacy
//    cost fields.
//
// Engine vocabulary inside a descriptor (else it is NOT config -> the line
// passes through at baseline):
//   fixed_price|price_override|override_price|flat_price   >0 pinned unit sell
//   tier_ref|tier_ref_id|pricing_tier_ref|bound_tier|tier|tier_name
//   per_unit_breaks|unit_breaks|qty_breaks                 qty chart
//   pricing_template_id|template_id|margin_template_id|
//     pricing_template_name|template_name|pricing_template|template
//   global_pricing_tier_id|pricing_tier_id|tier_set_id|pricing_tier_set_id|
//     pricing_rule_set_id|global_tier_id|global_pricing_tier_name|
//     pricing_tier_name|tier_set_name                      tier-set refs
//   market_retail|retail|retail_price|list_price           >0 market retail
//   market_discount_pct|retail_discount_pct
//   markup_pct|markup|markup_percent                       nonzero only
//   minimum_charge|min_charge|minimum|setup_fee_floor      extension floor
//   setup_fee|setupFee|setup_fee_flat                      flat sell fee
//   formula_modifiers|modifiers                            ordered unit-price ops
//   pricing_mode|price_mode|mode|active_mode               RECOGNIZED tokens
//     only ('market','market_based','market-based','retail',
//     'retail_minus_discount','fixed','fixed_price','flat','cost_plus',
//     'cost-plus','costplus','markup','tier','tier_markup','tiered') —
//     foundation unit enums like 'per_cy'/'per_bag'/'per_truck'/'per_day' are
//     NOT config
//   machine|machine_override|machine_pricing|equipment_pricing
//     (counts only when the descriptor itself carries engine fields)
//   customer_tier|customerTier                             line-scoped tier pin
//   tier_rules|tierRules|rules|matrix|matrix_rows|rows|pricing_matrix
//   templates|pricing_templates | tiers|tier_catalog|markup_tiers
//                                                          embedded registries
//   interpolate_breaks|interpolateBreaks|interpolate|
//     break_interpolation                                  qty-chart interpolation
//
// Caller-supplied `context` registries (tierRules, templates, tiers,
// customerTier, defaultMarkupPct, now) merge OVER the record-embedded block
// but never constitute engagement by themselves — engagement requires a
// record-carried context block or component-scoped config.
//
// Composition (brick/vinyl remainder model — the module markup is linear over
// the aggregate cost, so each priced line's baseline contribution is exactly
// lineCost * (1 + markupPct/100) where markupPct = customer_markup_percent):
//   remainder      = baselineSell - Σ pricedLineCost * (1 + markupPct/100)
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
// A flat customer_price_override rides the remainder — the override delta
// (override minus marked-up cost) stays module-priced alongside every
// unconfigured component, so an empty context block under an override lands
// back on the override verbatim. When a context block prices every line the
// remainder lands at baseline-minus-marked-up-cost and the engine owns the
// whole sell tail — including winning over a legacy saved customer_pricing
// snapshot (recorded in chain).
//
// The whole pipeline never throws; every step is echoed in `chain` and
// `warnings` for transparency. Configured lines without a finite cost base
// (possible only via an explicit input.lines[] override — foundationCostLines
// only emits finite-cost components) are SKIPPED at baseline, never repriced
// blind.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// Sum a numeric field over an array of records; null when the array is absent
// or no row contributes a finite value (caller falls back to qty 1).
const sumRows = (rows: unknown, field: string): number | null => {
  if (!Array.isArray(rows)) return null;
  let hit = false;
  let total = 0;
  for (const r of rows) {
    const n = toFiniteNumber(isRecord(r) ? r[field] : null);
    if (n === null) continue;
    hit = true;
    total += n;
  }
  return hit ? total : null;
};

