// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a maintenance sign/size/unit enum
 * (sign_type 'monument_sign', size 'cab_medium', material pricing_mode
 * 'per_letter_flat', usage_basis 'per_sqft', action id 'led_retrofit') or a
 * bare machine name must NOT flip the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// maintenance record -> normalized lines
// ---------------------------------------------------------------------------

export interface MaintenanceWireLine {
  /** Stable key — builder_item_id, else item id, else positional tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored, EXTENDED). null = unknown. */
  cost: number | null;
  category_key: string;
  /** The raw maintenance service-item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'caller' = input.lines override. */
  origin: 'items' | 'caller';
}

const lineKey = (item: Record<string, unknown>, index: number): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return `idx-${index}`;
};

/**
 * The line's module-authored EXTENDED cost base: a persisted single-total
 * field first (calcServiceItem's item_total_cost), else the labor_cost +
 * materials_cost component pair the page writes alongside it. null = no cost
 * base. Both spellings are already extended (the billable unit count is
 * folded in by the module), so no per-unit disambiguation is needed.
 */
const lineCostOf = (item: Record<string, unknown>): number | null => {
  const direct = firstFinite(item, LINE_COST_FIELDS);
  if (direct !== null) return direct;
  const hasComponent = LINE_COMPONENT_FIELDS.some((f) => toFiniteNumber(item[f]) !== null);
  if (!hasComponent) return null;
  return LINE_COMPONENT_FIELDS.reduce((s, f) => s + num(item[f]), 0);
};

/**
 * Normalize a MaintenanceProject-like record to the wire's line list. The
 * persisted flat `record.items` list is the only line source — service items
 * have no nested workflow structures, and the materials[]/actions[] rows
 * inside each item stay inside the line's cost base.
 */
export function maintenanceRecordLines(record: unknown): MaintenanceWireLine[] {
  if (!isRecord(record)) return [];
  const flat = (Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : []) as Record<string, unknown>[];
  return flat.map((item, index) => ({
    key: lineKey(item, index),
    index,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || asString(item.sign_type) || `Item ${index + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: lineCostOf(item),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin: 'items' as const,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface MaintenancePricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (the same percent that produced markup_amount — so a
 * configured-but-unresolved line naturally lands on its own baseline).
 */
export function maintenancePricingContextOf(record: unknown, callerContext: unknown = null): MaintenancePricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function maintenanceLineDescriptor(line: MaintenanceWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as MaintenanceWireLine)?.item)
    ? (line as MaintenanceWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of MAINTENANCE_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as MaintenanceWireLine)?.key]) ? lineMap[(line as MaintenanceWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as MaintenanceWireLine)?.index)]) ? lineMap[asString((line as MaintenanceWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface MaintenanceConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which maintenance service items carry pricing-engine
 * config. Cheap and side-effect free; callers may use it to decide whether
 * engine resolution is needed at all.
 */
export function maintenanceConfigScan(record: unknown, lines?: MaintenanceWireLine[]): MaintenanceConfigScan {
  const wireLines = Array.isArray(lines) ? lines : maintenanceRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = maintenanceLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolveMaintenanceSellPricing
// ---------------------------------------------------------------------------

export interface MaintenanceWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface MaintenanceSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface MaintenanceSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: MaintenanceSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: MaintenanceSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: MaintenanceSellLineResult[],
  chain: MaintenanceSellPricingResult['chain'],
  warnings: string[],
  contextUsed: MaintenanceSellPricingResult['context_used'],
): MaintenanceSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the maintenance project sell price through the injected pricing
 * engine.
 *
 * input.record          MaintenanceProject-like (items[])
 * input.lines           optional explicit MaintenanceWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.subtotal /
 *                       total_cost - markup_amount), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal
 * input.context         maintenancePricingContextOf-compatible registries
 *                       (merged over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveMaintenanceSellPricing(input: any = {}): MaintenanceSellPricingResult {
  const warnings: string[] = [];
  const chain: MaintenanceSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = maintenancePricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: MaintenanceWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: MaintenanceWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : maintenanceRecordLines(rec);

  const scan = maintenanceConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: MaintenanceSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = maintenanceLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : lineCostOf(rawItem);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: MaintenanceSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || asString(rawItem.sign_type) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Custom-items module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23j) —
// pure TS, ZERO imports, NO IO. Bundles clean for Deno base44 functions and
// the Vite frontend (frontend-shared-modules allowlist).
//
// What this does: the custom-items module's COST math stays authoritative —
// CustomItemsEstimator.jsx persists a flat items[] list of
// { description, quantity, item_total_cost, item_type, unit } rows where
// item_total_cost is the EXTENDED line cost (qty x unit — the page labels it
// "Cost (extended)", sumTotal() writes record.total_cost = Σ
// items[].item_total_cost, and partSync.extractManualItems derives
// unitCost = item_total_cost / quantity — the same extended semantics this
// wire uses). This wire only re-prices the SELL side of custom-items lines
// that carry a pricing-tier/template config. The engine is INJECTED by the
// caller ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ZERO-REGRESSION CONTRACT: a custom-items record whose lines carry no
// engine-vocab pricing config resolves { applied:false, passthrough:true,
// customer_price === baselineSell } — the caller returns the module's own
// sell price verbatim (byte-identical at the customerPricing seam).
// Custom-items records carry no module markup (total_cost is a pure cost
// total; the saved customer_pricing Markup-Tier snapshot is a separate
// layer), so the module markup factor is 1 and each configured line's
// baseline contribution is exactly its own line cost:
//
//   remainder      = baselineSell - Σ configured line cost
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
//
// Because the remainder only subtracts configured lines' costs, every
// un-configured line keeps its exact baseline contribution. markupPct still
// honors input.markupPercent / record.markup_percent / markup_amount÷subtotal
// for forward parity with the other module wires; on today's custom-items
// records it resolves to 0.
//
// ---------------------------------------------------------------------------
// Activation contract — "a line carrying a pricing-tier config"
// ---------------------------------------------------------------------------
// A custom-items line (record.items[] row — the persisted flat list) is
// engine-priced when its resolved descriptor carries at least one
// pricing-engine field:
//
//   fixed_price | price_override | override_price | flat_price   pinned unit sell
//   tier_ref | tier_ref_id | tier | tier_name | pricing_tier_ref  bound tier row
//   per_unit_breaks | unit_breaks | qty_breaks                    qty chart
//   pricing_template_id | template_id | margin_template_id |
//     pricing_template_name | template_name | pricing_template | template
//                                                              bound PricingTemplate
//   global_pricing_tier_id | pricing_tier_id | tier_set_id |
//     pricing_tier_set_id | pricing_rule_set_id | global_tier_id |
//     global_pricing_tier_name | pricing_tier_name | tier_set_name
//                                                              bound GlobalPricingTier
//   market_retail | retail | retail_price | list_price |
//     market_discount_pct | retail_discount_pct                 market-based pricing
//   pricing_mode | price_mode | mode   (engine tokens 'market' | 'market_based'
//     | 'market-based' | 'retail' | 'retail_minus_discount' | 'fixed' |
//     'fixed_price' | 'flat' ONLY — custom-items unit/type enums like
//     item_type 'fabrication' | 'material' | 'labor' | 'equipment' |
//     'shipping' | 'other', unit 'item', or mode spellings like 'per_item' /
//     'each' are NOT pricing config; description / quantity /
//     item_total_cost are cost-side fields and are never config)
//   markup_pct | markup | markup_percent                        part markup
//   minimum_charge | min_charge | minimum | setup_fee_floor     extension floor
//   setup_fee | setupFee | setup_fee_flat                       flat sell fee
//   formula_modifiers                                           ordered unit-price ops
//   machine | machine_override                                  descriptor w/ engine fields
//   customer_tier                                               line-scoped tier pin
//   tier_rules | tierRules | tier_matrix | templates |
//     pricing_templates | tiers                                 line-embedded registries
//   pricing | price_config | engine_pricing | pricing_config |
//     engine_price                                              nested config block
//
// Descriptor merge per line (weakest -> strongest):
//   flat item fields  <-  project engine_pricing.items[<line key>]  <-
//   item.pricing | .price_config | .engine_pricing | .pricing_config |
//   .engine_price nested block.
//
// Project-level context carrier (record.engine_pricing / .pricing_context /
// .engine_context / .pricing_engine — tolerated extras):
//   customer_tier, tier_rules | tierRules | tier_matrix, templates,
//   tiers | tier_catalog, default_markup_pct | defaultMarkupPct, now,
//   items | lines: { <item id|key|index>: <part descriptor> }.
// Caller-supplied `context` always outranks the record-embedded block; the
// record's saved Markup-Tier snapshot (customer_pricing.tier_number) is the
// weakest customer-tier source.
//
// Cost-base rule (safety): only lines with a finite numeric cost base can be
// engine-priced — the wire must subtract exactly the baseline sell it
// replaces. Custom-items spells it as the persisted item_total_cost extended
// total (first single-total field; line_total_cost | total_cost |
// extended_cost | line_cost | item_cost | cost | computed_cost tolerated);
// a machine_cost + labor_cost component pair is also honored as a tolerated
// extra (not a persisted custom-items shape). A configured line without a
// cost base is SKIPPED (skipped_no_cost warning, baseline untouched) rather
// than double-charging or zeroing sell dollars.
//
// qty: item.quantity | qty | count, default 1 — 0 is honored (extension 0,
// engine minimum never fires on extension <= 0). unitCost = lineCost/qty for
// qty > 0 else the raw lineCost — the same unitCost derivation
// extractManualItems uses. The whole pipeline never throws; every resolution
// step is echoed in `chain` for transparency.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/**
 * Line cost-base spellings (single-total fields; the persisted
 * item_total_cost extended line total first — the field
 * CustomItemsEstimator.jsx writes and sumTotal() sums into total_cost).
 * When none is present the wire falls back to a machine_cost + labor_cost
 * component pair — a tolerated extra, not a persisted custom-items shape.
 */
const LINE_COST_FIELDS = [
  'item_total_cost', 'line_total_cost', 'total_cost', 'extended_cost',
  'line_cost', 'item_cost', 'cost', 'computed_cost',
] as const;

/** Tolerated per-item cost components (not a persisted custom-items shape). */
const LINE_COST_COMPONENT_FIELDS = ['machine_cost', 'labor_cost'] as const;

const LINE_QTY_FIELDS = ['quantity', 'qty', 'count'] as const;

const LINE_LABEL_FIELDS = ['description', 'label', 'name', 'item_name', 'part_name'] as const;

/** The page writes no stable row id — real records key `idx-N` positionally. */
const LINE_KEY_FIELDS = ['builder_item_id', 'id', 'item_id', 'part_id', 'key', 'line_id'] as const;

/** item_type (fabrication|material|labor|equipment|shipping|other) doubles as the pricing category. */
const LINE_CATEGORY_FIELDS = ['category_key', 'category', 'part_category', 'pricing_category', 'item_type'] as const;

/** Project record blocks that may carry engine context + per-line overrides. */
const ENGINE_BLOCK_FIELDS = ['engine_pricing', 'pricing_context', 'engine_context', 'pricing_engine'] as const;

/** Nested per-item config blocks. */
const NESTED_CONFIG_FIELDS = ['pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price'] as const;

/** Map inside the project block keyed by line key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Pricing-mode tokens that count as engine config (unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog'] as const;

/**
 * Flat item fields the engine can read — copied into the line descriptor.
 * (Field names only; presence does not by itself mark the line configured —
 * see descriptorHasPricingContent.)
 */
export const CUSTOM_ITEMS_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  'unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

const anyFiniteField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => firstFinite(rec, [f]) !== null);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  return anyFiniteField(v, [...FIXED_FIELDS, ...MARKUP_FIELDS, ...MARKET_FIELDS, ...MIN_FIELDS])
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? An empty pricing:{} block, a custom-items unit/type enum
 * (item_type 'fabrication'|'material'|'labor'|'equipment'|'shipping'|'other',
 * unit 'item', mode 'per_item'|'each') or a bare machine name must NOT flip
 * the line out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  if (anyFiniteField(d, [...FIXED_FIELDS, ...MARKET_FIELDS, ...MARKET_DISCOUNT_FIELDS, ...MARKUP_FIELDS, ...MIN_FIELDS, ...SETUP_FIELDS])) return true;
  if (nonEmptyArrayField(d, [...BREAK_FIELDS, ...FORMULA_FIELDS, ...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => firstField(d, [f]) !== undefined)) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// Custom-items record -> normalized lines
// ---------------------------------------------------------------------------

export interface CustomItemsWireLine {
  /** Stable key — builder_item_id, else item id, else positional tag. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Line-level computed cost (module-authored). null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The raw custom-items item row. */
  item: Record<string, unknown>;
  /** 'items' = flat persisted list; 'caller' = input.lines override. */
  origin: 'items' | 'caller';
}

const lineKey = (item: Record<string, unknown>, index: number): string => {
  const explicit = firstField(item, LINE_KEY_FIELDS);
  if (explicit !== undefined && asString(explicit) !== '') return asString(explicit);
  return `idx-${index}`;
};

/**
 * The line's module-authored cost base: a persisted single-total field first
 * (the page's item_total_cost), else the machine_cost + labor_cost
 * component pair (tolerated extra), else null (no cost base).
 */
const lineCostOf = (item: Record<string, unknown>): number | null => {
  const direct = firstFinite(item, LINE_COST_FIELDS);
  if (direct !== null) return direct;
  const machine = toFiniteNumber(item.machine_cost);
  const labor = toFiniteNumber(item.labor_cost);
  if (machine === null && labor === null) return null;
  return num(machine) + num(labor);
};

/**
 * Normalize a CustomItemsProject-like record to the wire's line list. The persisted
 * flat `record.items` list is the only line source — the module has no
 * nested workflow structures.
 */
export function customItemsRecordLines(record: unknown): CustomItemsWireLine[] {
  if (!isRecord(record)) return [];
  const flat = Array.isArray(record.items) ? (record.items as unknown[]).filter(isRecord) : [];
  return flat.map((item, index) => ({
    key: lineKey(item, index),
    index,
    label: asString(firstField(item, LINE_LABEL_FIELDS)) || `Item ${index + 1}`,
    qty: num(firstField(item, LINE_QTY_FIELDS), 1),
    cost: lineCostOf(item),
    category_key: asString(firstField(item, LINE_CATEGORY_FIELDS)),
    item,
    origin: 'items' as const,
  }));
}

// ---------------------------------------------------------------------------
// project context carrier + per-line descriptor
// ---------------------------------------------------------------------------

const engineBlockOf = (record: unknown): Record<string, unknown> =>
  firstRecord(record as Record<string, unknown>, ENGINE_BLOCK_FIELDS) ?? {};

export interface CustomItemsPricingContext {
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  defaultMarkupPct: number;
  now: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > record.engine_pricing-style block > the record's
 * saved Markup-Tier snapshot tier_number > record.markup_percent as the
 * default markup (absent on custom-items records today, so 0 — a configured-but-
 * unresolved line then naturally lands on its own cost baseline).
 */
export function customItemsPricingContextOf(record: unknown, callerContext: unknown = null): CustomItemsPricingContext {
  const rec = isRecord(record) ? record : {};
  const block = engineBlockOf(rec);
  const caller = isRecord(callerContext) ? callerContext : {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(block, TIER_CONTEXT_FIELDS.concat('tier' as const))
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, ['tierRules', 'tier_rules', 'tier_matrix'])
    ?? firstArray(block, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, ['templates', 'pricing_templates'])
    ?? firstArray(block, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, ['tiers', 'tier_catalog', 'markup_tiers'])
    ?? firstArray(block, EMBEDDED_TIER_CATALOG_FIELDS.concat('markup_tiers' as const))
    ?? [];

  const defaultMarkupPct = firstFinite(caller, ['defaultMarkupPct', 'default_markup_pct'])
    ?? firstFinite(block, ['default_markup_pct', 'defaultMarkupPct'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  return {
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct,
    now: caller.now ?? block.now,
  };
}

/**
 * Per-line merged part descriptor (weakest -> strongest):
 * flat engine fields on the item -> project engine_pricing.items[key] ->
 * nested item pricing block. Returns null when no config source exists.
 */
export function customItemsLineDescriptor(line: CustomItemsWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const item = isRecord((line as CustomItemsWireLine)?.item)
    ? (line as CustomItemsWireLine).item
    : (isRecord(line) ? (line as Record<string, unknown>) : null);
  if (!item) return null;

  const flat: Record<string, unknown> = {};
  for (const f of CUSTOM_ITEMS_ENGINE_LINE_FIELDS) {
    if (item[f] !== undefined) flat[f] = item[f];
  }

  const block = engineBlockOf(record);
  const lineMap = firstRecord(block, ENGINE_LINE_MAP_FIELDS);
  const mapEntry = lineMap
    ? (isRecord(lineMap[(line as CustomItemsWireLine)?.key]) ? lineMap[(line as CustomItemsWireLine).key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as CustomItemsWireLine)?.index)]) ? lineMap[asString((line as CustomItemsWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = firstRecord(item, NESTED_CONFIG_FIELDS);

  const merged = { ...flat, ...(mapEntry ?? {}), ...(nested ?? {}) };
  if (!Object.keys(merged).length && !nested && !mapEntry) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface CustomItemsConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which custom-items lines carry pricing-engine config. Cheap and
 * side-effect free; callers may use it to decide whether engine resolution is
 * needed at all.
 */
export function customItemsConfigScan(record: unknown, lines?: CustomItemsWireLine[]): CustomItemsConfigScan {
  const wireLines = Array.isArray(lines) ? lines : customItemsRecordLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = customItemsLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

// ---------------------------------------------------------------------------
// resolveCustomItemsSellPricing
// ---------------------------------------------------------------------------

export interface CustomItemsWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface CustomItemsSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  configured: boolean;
  priced: boolean;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface CustomItemsSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: CustomItemsSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: CustomItemsSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  lines: CustomItemsSellLineResult[],
  chain: CustomItemsSellPricingResult['chain'],
  warnings: string[],
  contextUsed: CustomItemsSellPricingResult['context_used'],
): CustomItemsSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the custom-items project sell price through the injected pricing engine.
 *
 * input.record          CustomItemsProject-like (items[])
 * input.lines           optional explicit CustomItemsWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.total_cost), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal, else 0 (custom-items today)
 * input.context         customItemsPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveCustomItemsSellPricing(input: any = {}): CustomItemsSellPricingResult {
  const warnings: string[] = [];
  const chain: CustomItemsSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = customItemsPricingContextOf(rec, input.context);
  const contextUsed = {
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: CustomItemsWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: CustomItemsWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines
    : customItemsRecordLines(rec);

  const scan = customItemsConfigScan(rec, wireLines);
  chain.push({
    layer: 'config_scan',
    hit: scan.configured,
    won: false,
    detail: scan.configured
      ? `${scan.configuredCount} of ${scan.lineCount} lines carry pricing config`
      : `no pricing config on ${scan.lineCount} lines`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!scan.configured) return passthroughResult('no_config', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: CustomItemsSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const rawItem = isRecord(line?.item) ? line.item : (isRecord(line) ? (line as Record<string, unknown>) : {});
    const descriptor = customItemsLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Tolerate raw item rows passed via input.lines (qty/cost not yet folded).
    const cost = line.cost !== undefined ? line.cost : lineCostOf(rawItem);
    const qty = (num(line.qty ?? firstField(rawItem, LINE_QTY_FIELDS), 1) || 0);
    const base: CustomItemsSellLineResult = {
      key: line.key || lineKey(rawItem, position),
      label: line.label || asString(firstField(rawItem, LINE_LABEL_FIELDS)) || `Item ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!configured) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`line '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // GlobalPricingTier chart resolves the unit price, then the descriptor
    // adapter encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...descriptor };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `line '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`line '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? null;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? undefined;
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? undefined;
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : undefined;

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'])) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`line '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`line '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`configured lines' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - configured baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Shared pricing engine — pure, deterministic, zero entity/io access.
//
// Importable by Deno-style base44 functions AND the Vite frontend: no node:*,
// no npm:*, no imports at all. Callers hand the engine plain row objects
// (PricingTierMatrix-like chart rows, part/machine override descriptors) and
// get back fully-traced price breakdowns.
//
// Pipeline (pricePart): cost base -> tier lookup -> markup/fixed/market unit
// price -> formula modifiers -> qty extension -> minimum charge -> setup fee
// -> tax -> total.
//
// Tier precedence (resolveTier) follows the CoreBridge section-8 chain —
// "customer tier -> part-specific tier/fixed -> machine override" — read as a
// base-to-override ladder: the global default is the base, each configured
// layer overrides the previous one, so the MOST SPECIFIC layer wins:
//
//   machine_override  (strongest: the machine the part runs on)
//   part_fixed        (explicit sell price pinned on the part)
//   part_tier         (part-bound tier ref / part qty chart / part markup)
//   customer_tier     (chart row pinning the customer's assigned tier)
//   global_default    (weakest: category/blank chart row, else defaultMarkupPct)
//
// WITHIN the two chart-row layers the winning row follows legacy
// matchSpecificity (src/components/pricing/pricingEngine.js resolveMatrixRow):
// cat+tier (3) > cat-only (2) > tier-only (1) > blank (0) — so a
// category-pinned default row still outranks a bare customer_tier row even
// though it lives in the "weaker" ladder layer (F-27 parity). Part/machine
// descriptors keep the strict ladder ordering above the chart.
//
// Money semantics mirror src/components/pricing/pricingEngine.js:
//   markup_pct is a PERCENT over cost (50 = cost x 1.50); market mode stores a
//   retail price minus a discount percent; per_unit_breaks are qty thresholds
//   {qty, unit_price} where the highest qualifying bracket wins (in market
//   mode a break only wins when it undercuts the market unit price).
//   Money figures round to cents (round2); unit prices to 4 decimals (round4).

const num = (v: unknown, fallback = 0): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

const normStr = (v: unknown): string => String(v ?? '').trim().toLowerCase();

export const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;
export const round4 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 10000) / 10000;

// Weakest -> strongest. resolveTier walks this order for the OVERRIDE layers
// (part/machine); the two chart-row layers beneath them compete on legacy
// row specificity instead of raw layer order (see the header block above).
export const TIER_PRECEDENCE = Object.freeze([
  'global_default',
  'customer_tier',
  'part_tier',
  'part_fixed',
  'machine_override',
] as const);

export type TierSource = typeof TIER_PRECEDENCE[number];

export const PRICING_MODES = Object.freeze({
  MARKUP: 'markup',
  COST_PLUS: 'cost_plus',
  MARKET: 'market',
  // F-05 activation vocabulary: 'market_based' is the entity/admin spelling of
  // the same retail-minus-discount chart family the engine rows call 'market'
  // (PricingTemplate.market_based, GlobalPricingTier.rules[].market_based).
  // 'fixed' is a pinned unit sell price (part.fixed_price family).
  MARKET_BASED: 'market_based',
  FIXED: 'fixed',
} as const);

// --- Date windows (chart rows may carry effective_from / effective_to) --------

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;
const toTime = (v: unknown, { endOfDay = false } = {}): number | null => {
  if (v == null || v === '') return null;
  if (v instanceof Date) {
    const t = v.getTime();
    return Number.isFinite(t) ? t : null;
  }
  const s = String(v).trim();
  if (!s) return null;
  const t = Date.parse(s);
  if (!Number.isFinite(t)) return null;
  return endOfDay && DATE_ONLY.test(s) ? t + 86399999 : t;
};

const rowIsActive = (row: any): boolean => normStr(row?.status ?? 'active') !== 'inactive';

export function rowIsEffective(row: any, now: unknown = new Date()): boolean {
  const t = now instanceof Date ? now.getTime() : toTime(now);
  const at = Number.isFinite(t) ? (t as number) : Date.now();
  const from = toTime(row?.effective_from);
  const to = toTime(row?.effective_to, { endOfDay: true });
  if (from != null && at < from) return false;
  if (to != null && at > to) return false;
  return true;
}

// --- Tier key matching ---------------------------------------------------------

// A customerTier may arrive as a MarkupTier-like record ({id, tier_name,
// tier_number, name}) or a bare string/number. Rows match on whichever of
// tier_name / tier_number / id / name the admin typed into customer_tier.
const tierKeySet = (customerTier: unknown): Set<string> => {
  const keys = new Set<string>();
  const add = (v: unknown) => {
    const k = normStr(v);
    if (k) keys.add(k);
  };
  if (customerTier && typeof customerTier === 'object') {
    const t: any = customerTier;
    add(t.tier_name);
    add(t.tier_number);
    add(t.id);
    add(t.name);
  } else {
    add(customerTier);
  }
  return keys;
};

const rowPinsTier = (row: any, tierKeys: Set<string>): boolean =>
  !!normStr(row?.customer_tier) && tierKeys.has(normStr(row?.customer_tier));

const rowFitsCategory = (row: any, category: unknown): boolean =>
  !normStr(row?.category) || normStr(row?.category) === normStr(category);

// Deterministic tie-break inside a match bucket: most recent effective_from,
// then most recent updated_date, then lowest id.
const newerRow = (a: any, b: any): any => {
  if (!b) return a;
  const aFrom = toTime(a?.effective_from) ?? -Infinity;
  const bFrom = toTime(b?.effective_from) ?? -Infinity;
  if (aFrom !== bFrom) return aFrom > bFrom ? a : b;
  const aUp = toTime(a?.updated_date) ?? -Infinity;
  const bUp = toTime(b?.updated_date) ?? -Infinity;
  if (aUp !== bUp) return aUp > bUp ? a : b;
  return String(a?.id || '') <= String(b?.id || '') ? a : b;
};

// --- Qty-break charts -----------------------------------------------------------

// The bracket with the highest qualifying `qty` threshold wins.
// opts.interpolate === true switches to linear interpolation between bracket
// points (see interpolateUnitBreak). With opts absent/false the pick is
// byte-for-byte the legacy bracket pick — callers never interpolate unless a
// chart explicitly opts in (interpolate_breaks / break_interpolation:'linear').
export function pickUnitBreak(breaks: any, qty: unknown, opts: any = {}): any {
  const q = num(qty);
  if (!Array.isArray(breaks) || q <= 0) return null;
  if (opts && opts.interpolate === true) return interpolateUnitBreak(breaks, q);
  let pick: any = null;
  for (const b of breaks) {
    const bq = num(b?.qty, NaN);
    if (!Number.isFinite(bq) || bq <= 0 || bq > q) continue;
    if (!Number.isFinite(Number(b?.unit_price))) continue;
    if (!pick || bq > num(pick.qty)) pick = b;
  }
  return pick;
}

// Valid brackets ({qty>0, finite unit_price}) sorted ascending by qty with
// duplicate thresholds collapsed — the first-declared bracket wins its slot.
// This is the lattice interpolation walks.
const sortedUnitBreaks = (breaks: any): any[] => {
  const list: any[] = [];
  for (const b of Array.isArray(breaks) ? breaks : []) {
    const bq = num(b?.qty, NaN);
    if (!Number.isFinite(bq) || bq <= 0) continue;
    if (!Number.isFinite(Number(b?.unit_price))) continue;
    list.push(b);
  }
  list.sort((a: any, b: any) => num(a.qty) - num(b.qty));
  return list.filter((b: any, i: number) => i === 0 || num(b.qty) !== num(list[i - 1].qty));
};

// Linear interpolation between neighboring bracket points (F-04 — CoreBridge
// interpolated qty-break charts). Semantics:
//   qty in [lo.qty, hi.qty): unit_price = lo.p + (hi.p - lo.p) * t where
//     t = (qty - lo.qty) / (hi.qty - lo.qty); result rounds to 4 decimals
//     (round4 — same precision as every engine unit price).
//   qty below the FIRST bracket  -> null (never extrapolate below the chart;
//     the caller falls back to markup/market exactly like a missed break).
//   qty exactly ON a bracket qty -> that bracket object verbatim.
//   qty at/above the TOP bracket -> top bracket verbatim (clamp — the best
//     published volume price, never an extrapolation off the chart's end).
//   0 or 1 valid brackets        -> plain bracket-pick semantics.
// Mid-bracket hits return a synthetic bracket
//   {qty: lower.qty, unit_price, interpolated: true, at_qty: <requested>,
//    between: [lowerBracket, upperBracket]}
// so a downstream `breakApplied` audit can show the interpolation anchors.
export function interpolateUnitBreak(breaks: any, qty: unknown): any {
  const q = num(qty);
  const list = sortedUnitBreaks(breaks);
  if (!list.length || q <= 0 || q < num(list[0].qty)) return null;
  const last = list[list.length - 1];
  if (q >= num(last.qty)) return last;
  let lower = list[0];
  let upper = last;
  for (let i = 0; i < list.length - 1; i += 1) {
    if (q < num(list[i + 1].qty)) {
      lower = list[i];
      upper = list[i + 1];
      break;
    }
  }
  if (q === num(lower.qty)) return lower;
  const loQ = num(lower.qty);
  const hiQ = num(upper.qty);
  const loP = num(lower.unit_price);
  const hiP = num(upper.unit_price);
  const t = (q - loQ) / (hiQ - loQ);
  return {
    qty: loQ,
    unit_price: round4(loP + (hiP - loP) * t),
    interpolated: true,
    at_qty: q,
    between: [lower, upper],
  };
}

// --- Formula modifiers -----------------------------------------------------------

// Ordered unit-price adjustments, applied left-to-right ({type, value}):
//   add_pct  price = price x (1 + value/100)   (negative discounts)
//   mul      price = price x value
//   add_flat price = price + value
//   min      price = max(price, value)         (unit floor)
//   max      price = min(price, value)         (unit cap)
// Unknown types / non-finite values are skipped; price can never go below 0.
export function applyFormulaModifiers(unitPrice: unknown, modifiers: any): { unitPrice: number; applied: any[] } {
  let price = num(unitPrice);
  const applied: any[] = [];
  for (const m of Array.isArray(modifiers) ? modifiers : []) {
    const type = normStr(m?.type);
    const value = Number(m?.value);
    if (!Number.isFinite(value)) continue;
    const before = price;
    if (type === 'add_pct') price = price * (1 + value / 100);
    else if (type === 'mul') price = price * value;
    else if (type === 'add_flat') price = price + value;
    else if (type === 'min') price = Math.max(price, value);
    else if (type === 'max') price = Math.min(price, value);
    else continue;
    price = Math.max(0, price);
    applied.push({ type, value, before: round4(before), after: round4(price) });
  }
  return { unitPrice: round4(price), applied };
}

// --- Rule normalization ------------------------------------------------------------
//
// Every pricing layer resolves to one normalized rule:
//   kind: 'fixed' | 'markup' | 'market' | 'breaks'
//   fixedPrice?         unit sell price (fixed)
//   markupPct?          percent over unit cost (markup; also breaks fallback)
//   marketRetail?       market list price (market)
//   marketDiscountPct?  percent off retail (market)
//   unitBreaks?         [{qty, unit_price}] qty-break chart
//   minimumCharge?      extension floor
//   formulaModifiers?   ordered unit-price adjustments
//   ref?                originating record/descriptor (echoed for audit)

const marketKind = (row: any): boolean => {
  const pm = normStr(row?.pricing_mode);
  // 'market' is the engine token; 'market_based' is the entity/admin spelling
  // of the same chart family — both require a POSITIVE finite market_retail.
  // Legacy parity (F-27): retail <= 0 / non-finite is treated as absent — the
  // row falls back to its markup path exactly like resolveEffectivePrice's
  // `retail > 0` gate (pricingEngine.js).
  return (pm === PRICING_MODES.MARKET || pm === PRICING_MODES.MARKET_BASED)
    && Number.isFinite(Number(row?.market_retail)) && Number(row?.market_retail) > 0;
};

// A chart row / override descriptor opts its qty-break chart into interpolated
// pricing via interpolate_breaks (boolean | 'true' | 'linear'), the camelCase
// twins interpolateBreaks/interpolate, or break_interpolation:'linear'.
// Off by default — every unflagged chart keeps exact bracket-pick semantics.
const wantsInterpolatedBreaks = (src: any): boolean => {
  if (!src || typeof src !== 'object') return false;
  if (normStr(src.break_interpolation) === 'linear') return true;
  for (const f of ['interpolate_breaks', 'interpolateBreaks', 'interpolate']) {
    const v = (src as any)[f];
    if (v === true || normStr(v) === 'true' || normStr(v) === 'linear') return true;
  }
  return false;
};

function ruleFromChartRow(row: any): any {
  return {
    kind: marketKind(row) ? 'market' : 'markup',
    markupPct: num(row?.markup_pct),
    marketRetail: marketKind(row) ? num(row?.market_retail) : undefined,
    marketDiscountPct: marketKind(row) ? num(row?.market_discount_pct) : undefined,
    unitBreaks: Array.isArray(row?.per_unit_breaks) ? row.per_unit_breaks : undefined,
    interpolateBreaks: wantsInterpolatedBreaks(row) || undefined,
    minimumCharge: Number.isFinite(Number(row?.minimum_charge)) ? num(row.minimum_charge) : undefined,
    formulaModifiers: Array.isArray(row?.formula_modifiers) ? row.formula_modifiers : undefined,
    ref: row,
  };
}

const firstFinite = (...vals: unknown[]): number | null => {
  for (const v of vals) if (Number.isFinite(Number(v))) return Number(v);
  return null;
};

// Candidate rule from a part- or machine-shaped override descriptor.
// Within a layer: fixed_price > tier_ref > per_unit_breaks > pricing_mode
// 'market' > markup_pct. Returns null when the descriptor overrides nothing.
function overrideRule(source: any, tierRules: any[]): any {
  if (!source || typeof source !== 'object') return null;

  const fixed = firstFinite(source.fixed_price, source.price_override, source.override_price);
  if (fixed != null && fixed > 0) {
    return {
      kind: 'fixed',
      fixedPrice: fixed,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  const tierRef = source.tier_ref ?? source.tier ?? source.tier_name;
  if (tierRef != null && normStr(tierRef)) {
    const wanted = normStr(typeof tierRef === 'object' ? (tierRef as any).name ?? (tierRef as any).id : tierRef);
    const row = (Array.isArray(tierRules) ? tierRules : []).find(
      (r: any) => r && rowIsActive(r) && (normStr(r.name) === wanted || normStr(r.id) === wanted),
    );
    if (row) return ruleFromChartRow(row);
    // A dangling tier ref must NOT silently fall through to weaker layers —
    // report it as an unpriced hit so the caller sees the misconfiguration.
    return { kind: 'markup', markupPct: 0, ref: source, danglingTierRef: String(wanted) };
  }

  const breaks = Array.isArray(source.per_unit_breaks) ? source.per_unit_breaks
    : Array.isArray(source.unit_breaks) ? source.unit_breaks
    : null;
  if (breaks && breaks.length) {
    return {
      kind: 'breaks',
      unitBreaks: breaks,
      interpolateBreaks: wantsInterpolatedBreaks(source) || undefined,
      markupPct: firstFinite(source.markup_pct) ?? undefined,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  if (marketKind(source)) {
    return {
      kind: 'market',
      marketRetail: num(source.market_retail),
      marketDiscountPct: num(source.market_discount_pct),
      unitBreaks: Array.isArray(source.per_unit_breaks) ? source.per_unit_breaks : undefined,
      interpolateBreaks: wantsInterpolatedBreaks(source) || undefined,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  const markup = firstFinite(source.markup_pct);
  if (markup != null && markup !== 0) {
    return {
      kind: 'markup',
      markupPct: markup,
      interpolateBreaks: wantsInterpolatedBreaks(source) || undefined,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  return null;
}

// --- resolveTier -------------------------------------------------------------------
//
// context:
//   customerTier      assigned tier (string | number | MarkupTier-like record)
//   category          line category key (chart rows may pin a category)
//   tierRules         pricing chart rows (PricingTierMatrix-like)
//   part              part-level override descriptor
//   machine           machine-level override descriptor
//   defaultMarkupPct  shop fallback percent over cost
//   now               override for effective-window checks (tests)
//
// Returns { source, rule, layer, trace } where trace walks the ladder
// base -> override and marks which layers were hit and which one won.
export function resolveTier({
  customerTier = null,
  category = '',
  tierRules = [],
  part = null,
  machine = null,
  defaultMarkupPct = 0,
  now = undefined,
}: any = {}): any {
  const rules = Array.isArray(tierRules) ? tierRules : [];
  const tierKeys = tierKeySet(customerTier);
  const eligible = rules.filter((r: any) => r && rowIsActive(r) && rowIsEffective(r, now) && rowFitsCategory(r, category));

  // Customer-tier layer: rows that PIN this customer's tier.
  // category+tier beats tier-only inside the layer.
  let tierRow: any = null;
  let tierRowScoped = false;
  for (const row of eligible) {
    if (!rowPinsTier(row, tierKeys)) continue;
    const scoped = !!normStr(row.category);
    if (!tierRow || (scoped && !tierRowScoped) || scoped === tierRowScoped) {
      if (!tierRow || (scoped && !tierRowScoped)) { tierRow = row; tierRowScoped = scoped; }
      else tierRow = newerRow(row, tierRow);
    }
  }

  // Global-default layer: rows that pin NO tier — category rows beat blank
  // rows; failing both, the shop defaultMarkupPct is the implicit rule.
  let catRow: any = null;
  let blankRow: any = null;
  for (const row of eligible) {
    if (normStr(row.customer_tier)) continue;
    if (normStr(row.category)) catRow = newerRow(row, catRow);
    else blankRow = newerRow(row, blankRow);
  }

  // Part layer: fixed price outranks the part's own tier/chart/markup.
  const partRule = overrideRule(part, rules);
  const partSource = partRule?.kind === 'fixed' ? 'part_fixed' : 'part_tier';

  // Machine layer: anything the machine descriptor overrides wins outright.
  const machineRule = overrideRule(machine, rules);

  const defaultRule = catRow || blankRow
    ? ruleFromChartRow(catRow || blankRow)
    : { kind: 'markup', markupPct: num(defaultMarkupPct), ref: null, implicit: true };

  const ladder: any[] = [
    { layer: 'global_default', source: 'global_default', rule: defaultRule, hit: true,
      detail: catRow ? 'category_row' : blankRow ? 'blank_row' : 'default_markup_pct' },
    { layer: 'customer_tier', source: 'customer_tier', rule: tierRow ? ruleFromChartRow(tierRow) : null,
      hit: !!tierRow, detail: tierRow ? (tierRowScoped ? 'category+tier' : 'tier') : 'no tier row' },
    { layer: 'part', source: partSource, rule: partRule, hit: !!partRule,
      detail: partRule ? partRule.kind : 'no part override' },
    { layer: 'machine', source: 'machine_override', rule: machineRule, hit: !!machineRule,
      detail: machineRule ? machineRule.kind : 'no machine override' },
  ];

  // Chart-row layers compete on legacy matchSpecificity, NOT ladder order
  // (F-27 parity with resolveMatrixRow): cat+tier (3) > cat-only (2) >
  // tier-only (1) > blank (0). Scores never tie across layers (tier adds 1,
  // category adds 2), and each layer's row is already its best by the shared
  // tie-break (scoped > unscoped, then effective_from -> updated_date -> id).
  // The implicit defaultMarkupPct rule only wins when no chart row matched.
  const tierRowSpec = tierRow ? (tierRowScoped ? 3 : 1) : -1;
  const defaultRowSpec = catRow ? 2 : blankRow ? 0 : -1;
  let winner = tierRowSpec > defaultRowSpec ? ladder[1] : ladder[0];
  // Part/machine descriptors still override the winning chart layer in order.
  for (const step of ladder.slice(2)) if (step.hit && step.rule) winner = step;

  return {
    source: winner.source as TierSource,
    layer: winner.layer,
    rule: winner.rule,
    matchedRow: winner.rule?.ref ?? null,
    trace: ladder.map((step) => ({
      layer: step.layer,
      source: step.source,
      hit: step.hit,
      won: step === winner,
      detail: step.detail,
    })),
  };
}

// --- pricePart ---------------------------------------------------------------------
//
// input:
//   label, category, qty, unitCost (internal cost base per pricing unit),
//   pricingUnit (echo only — caller measures qty in pricing units),
//   customerTier, tierRules, part, machine, defaultMarkupPct  -> resolveTier
//   setupFee        flat dollars added after the minimum floor
//   minimumCharge   caller-side floor; combined with the winning rule's own
//                   minimum_charge (the higher floor wins)
//   taxable         false exempts the whole line (incl. setup fee) from tax
//   taxPercent      percent applied to (extension + setupFee) when taxable
//   modifiers       caller-level formula modifiers (run after rule modifiers)
//   now             effective-window override
//
// Returns a fully-traced breakdown. Never throws on bad numbers — non-finite
// inputs coerce to 0. Legacy parity (F-27): qty/unitCost pass through
// UNCLAMPED exactly like pricingEngine.js num() — a negative qty or cost
// yields a negative extension (minimums still never fire on extension <= 0).
export function pricePart(input: any = {}): any {
  const qty = num(input.qty ?? input.quantity, 0);
  const unitCost = num(input.unitCost ?? input.cost ?? input.costBase);
  const tier = resolveTier(input);
  const rule = tier.rule || { kind: 'markup', markupPct: 0 };

  let unitPrice = 0;
  let priceSource = 'cost_passthrough';
  let breakApplied: any = null;
  let market: any = null;

  const breaks = Array.isArray(rule.unitBreaks) ? rule.unitBreaks : null;
  // Interpolated break charts opt in via rule.interpolateBreaks (matrix row /
  // descriptor flag) — unflagged charts keep exact bracket-pick semantics.
  const brk = breaks ? pickUnitBreak(breaks, qty, { interpolate: rule.interpolateBreaks === true }) : null;

  if (rule.kind === 'fixed') {
    unitPrice = num(rule.fixedPrice);
    priceSource = 'fixed_price';
  } else if (rule.kind === 'market') {
    const retail = num(rule.marketRetail);
    const discountPct = num(rule.marketDiscountPct);
    const marketUnit = Math.max(0, retail * (1 - discountPct / 100));
    // A volume break must actually beat the market unit price to win.
    if (brk && num(brk.unit_price) < marketUnit) {
      unitPrice = num(brk.unit_price);
      priceSource = 'qty_break';
      breakApplied = brk;
    } else {
      unitPrice = marketUnit;
      priceSource = 'market';
    }
    market = { marketRetail: retail, marketDiscountPct: discountPct, marketUnit: round4(marketUnit) };
  } else if (rule.kind === 'breaks') {
    if (brk) {
      unitPrice = num(brk.unit_price);
      priceSource = 'qty_break';
      breakApplied = brk;
    } else {
      // No qualifying bracket — fall back to the descriptor's markup (or cost).
      unitPrice = unitCost * (1 + num(rule.markupPct) / 100);
      priceSource = Number.isFinite(Number(rule.markupPct)) ? 'markup' : 'cost_passthrough';
    }
  } else {
    // markup: a qualifying qty break beats the markup chart outright.
    if (brk) {
      unitPrice = num(brk.unit_price);
      priceSource = 'qty_break';
      breakApplied = brk;
    } else {
      unitPrice = unitCost * (1 + num(rule.markupPct) / 100);
      priceSource = 'markup';
    }
  }

  const baseUnitPrice = unitPrice;
  // Caller modifiers identical to rule-borne ones must not double-apply — a
  // caller that forwards a part's own formula_modifiers as input.modifiers
  // would otherwise run the same adjustment twice. Dedupe by (type, value);
  // distinct modifiers still stack in order.
  const ruleMods = Array.isArray(rule.formulaModifiers) ? rule.formulaModifiers : [];
  const ruleModKeys = new Set(ruleMods.map((m: any) => `${normStr(m?.type)}|${Number(m?.value)}`));
  const callerMods = (Array.isArray(input.modifiers) ? input.modifiers : [])
    .filter((m: any) => !ruleModKeys.has(`${normStr(m?.type)}|${Number(m?.value)}`));
  const modResult = applyFormulaModifiers(unitPrice, [...ruleMods, ...callerMods]);
  unitPrice = modResult.unitPrice;

  const extension = round2(unitPrice * qty);
  const ruleMin = num(rule.minimumCharge);
  const callerMin = num(input.minimumCharge);
  const minimumCharge = Math.max(ruleMin, callerMin);
  const minimumApplied = minimumCharge > 0 && extension > 0 && extension < minimumCharge;
  const extended = minimumApplied ? round2(minimumCharge) : extension;

  const setupFee = Math.max(0, num(input.setupFee ?? input.setup_fee));
  const subtotal = round2(extended + setupFee);

  const taxable = input.taxable !== false;
  const taxPercent = Math.max(0, num(input.taxPercent ?? input.tax_percent));
  const tax = taxable ? round2(subtotal * (taxPercent / 100)) : 0;
  const total = round2(subtotal + tax);

  return {
    label: String(input.label ?? ''),
    category: String(input.category ?? ''),
    pricingUnit: String(input.pricingUnit ?? input.pricing_unit ?? 'each'),
    qty,
    unitCost,
    tier,
    rule,
    baseUnitPrice: round4(baseUnitPrice),
    unitPrice: round4(unitPrice),
    priceSource,
    breakApplied,
    market,
    modifiersApplied: modResult.applied,
    extension,
    minimumCharge: minimumCharge > 0 ? minimumCharge : 0,
    minimumApplied,
    extended,
    setupFee,
    subtotal,
    taxable,
    taxPercent,
    tax,
    total,
    danglingTierRef: rule.danglingTierRef || null,
  };
}

// --- priceLines ----------------------------------------------------------------------
//
// Convenience roll-up: pricePart over an array of lines sharing the same
// context (customerTier, tierRules, taxPercent...). Per-line `part`, `machine`,
// `taxable`, `setupFee`, `minimumCharge`, `modifiers` stay on each line object.
export function priceLines({ lines = [], ...shared }: any = {}): any {
  const priced = (Array.isArray(lines) ? lines : []).map((line: any, index: number) =>
    pricePart({ label: line?.label ?? `Line ${index + 1}`, ...shared, ...line }));

  const extended = round2(priced.reduce((s: number, l: any) => s + l.extended, 0));
  const setupFees = round2(priced.reduce((s: number, l: any) => s + l.setupFee, 0));
  const subtotal = round2(priced.reduce((s: number, l: any) => s + l.subtotal, 0));
  const tax = round2(priced.reduce((s: number, l: any) => s + l.tax, 0));
  const total = round2(priced.reduce((s: number, l: any) => s + l.total, 0));

  return {
    lines: priced,
    extended,
    setupFees,
    subtotal,
    tax,
    total,
    minimumsApplied: priced
      .map((l: any, index: number) => (l.minimumApplied
        ? { index, label: l.label, extension: l.extension, minimumCharge: l.minimumCharge, source: l.tier.source }
        : null))
      .filter(Boolean),
  };
}

// --- Entity activation layer (F-04 / F-05) -------------------------------------
//
// The engine resolves plain chart-row objects; this section bridges persisted
// Base44 entity shapes to those rows. Still pure/deterministic — no io.
//
// PricingTierMatrix.jsonc field reality (verified against the schema):
//   name, status ('active'|'inactive'), customer_tier (MarkupTier.tier_name /
//   tier_number / record id; blank = every tier), category (MarkupCategory
//   .category_key; blank = every category), markup_pct, minimum_charge,
//   per_unit_breaks [{qty, unit_price}], effective_from / effective_to
//   (YYYY-MM-DD; `to` inclusive through end of day), updated_by, updated_note,
//   sort_order — plus tolerated extras the engine understands when present:
//   pricing_mode ('market'|'market_based'), market_retail,
//   market_discount_pct, formula_modifiers, interpolate_breaks.
//
// matrixRowToRule normalizes one row: tolerated aliases collapse onto the
// canonical engine fields (unit_breaks / qty_breaks -> per_unit_breaks; bracket
// {price|unit_price} and {qty|min_qty|quantity} -> {qty, unit_price};
// 'market-based' -> 'market_based'; retail / retail_price -> market_retail;
// discount_pct -> market_discount_pct; any interpolation spelling ->
// interpolate_breaks:true). Break charts are sanitized: non-positive qty and
// non-finite price brackets drop; a chart emptied that way is removed entirely
// so it can't mask the markup path. NOTE `breaks` is deliberately NOT aliased —
// PricingTemplate.breaks carries {qty, tier_markups} which is a different
// chart, not a {qty, unit_price} list.
//
// matrixRowsToRules applies the row gate the entity contract requires —
// status:'inactive' rows and rows outside their effective_from/effective_to
// window (checked at `now`) never reach the resolver — then maps each
// survivor through matrixRowToRule. Output rows are drop-in `tierRules` for
// resolveTier / pricePart (which re-check status + window themselves, so a
// stale adapted list still can't price an expired row).
export function matrixRowToRule(row: any, opts: any = {}): any {
  if (!row || typeof row !== 'object') return null;
  const out: any = { ...row };

  // Canonical status token: anything but 'inactive' is live (blank = active).
  out.status = normStr(row.status) === 'inactive' ? 'inactive' : 'active';

  const rawBreaks = Array.isArray(row.per_unit_breaks) ? row.per_unit_breaks
    : Array.isArray(row.unit_breaks) ? row.unit_breaks
    : Array.isArray(row.qty_breaks) ? row.qty_breaks
    : null;
  if (rawBreaks) {
    const clean = rawBreaks
      .map((b: any) => ({
        qty: num(b?.qty ?? b?.min_qty ?? b?.quantity, NaN),
        unit_price: num(b?.unit_price ?? b?.price, NaN),
      }))
      .filter((b: any) => Number.isFinite(b.qty) && b.qty > 0 && Number.isFinite(b.unit_price));
    if (clean.length) out.per_unit_breaks = clean;
    else delete out.per_unit_breaks;
  }

  if (normStr(out.pricing_mode) === 'market-based') out.pricing_mode = 'market_based';
  const retail = firstFinite(row.market_retail, row.retail_price, row.retail);
  if (retail != null) out.market_retail = retail;
  const discount = firstFinite(row.market_discount_pct, row.discount_pct);
  if (discount != null) out.market_discount_pct = discount;

  if (wantsInterpolatedBreaks(row) || opts.interpolateBreaks === true) {
    out.interpolate_breaks = true;
  }
  return out;
}

export function matrixRowsToRules(rows: any, opts: any = {}): any[] {
  const now = opts.now ?? new Date();
  const list = Array.isArray(rows) ? rows : Array.isArray(rows?.rows) ? rows.rows : [];
  const out: any[] = [];
  for (const row of list) {
    if (!row || typeof row !== 'object') continue;
    if (!rowIsActive(row)) continue;          // status:'inactive' never competes
    if (!rowIsEffective(row, now)) continue;  // effective_from/to window (entity field names)
    out.push(matrixRowToRule(row, opts));
  }
  return out;
}

// --- resolvePricingMode -----------------------------------------------------------
//
// Which pricing FAMILY a part prices under (F-05):
//   'cost_plus'    markup over unit cost — includes the %-tier matrix chart;
//                  PricingMode.active_mode 'tier' maps here.
//   'market_based' retail minus discount — PricingTemplate.market_based /
//                  GlobalPricingTier rule market_based / market_retail data.
//   'fixed'        pinned unit sell price (fixed_price / price_override family).
//
// Precedence: part > template > globalDefault > 'cost_plus' fallback.
// Within each layer: explicit mode token > fixed_price > bound tier_ref's
// chart row > market signals — mirroring overrideRule's own precedence.
//   { part, template, globalDefault, tierRules }
//   part          part-level descriptor. Field-name trap: inventory entities
//                 use `pricing_mode` for UNIT enums ('per_piece', 'per_roll'…)
//                 — unrecognized tokens are skipped, never guessed as a family.
//   template      PricingTemplate-like ({market_based, breaks, ...}) or any
//                 descriptor carrying the same signals.
//   globalDefault PricingMode entity ({active_mode:'tier'|'cost_plus'}),
//                 a settings-like object, or a bare mode string.
//   tierRules     optional chart rows so a bound tier_ref resolves to its row's
//                 family (a dangling ref resolves nothing — falls through).
// Returns {mode, source:'part'|'template'|'global'|'default', raw, via}.

const MODE_TOKENS: Record<string, string> = {
  fixed: PRICING_MODES.FIXED,
  fixed_price: PRICING_MODES.FIXED,
  flat: PRICING_MODES.FIXED,
  market: PRICING_MODES.MARKET_BASED,
  market_based: PRICING_MODES.MARKET_BASED,
  'market-based': PRICING_MODES.MARKET_BASED,
  retail: PRICING_MODES.MARKET_BASED,
  retail_minus_discount: PRICING_MODES.MARKET_BASED,
  cost_plus: PRICING_MODES.COST_PLUS,
  'cost-plus': PRICING_MODES.COST_PLUS,
  costplus: PRICING_MODES.COST_PLUS,
  markup: PRICING_MODES.COST_PLUS,
  tier: PRICING_MODES.COST_PLUS,
  tier_markup: PRICING_MODES.COST_PLUS,
  tiered: PRICING_MODES.COST_PLUS,
};

export const normalizePricingMode = (v: unknown): string | null =>
  MODE_TOKENS[normStr(v)] ?? null;

// Explicit token fields, checked in order. A bare string/number descriptor is
// itself the token (via:'value').
const explicitModeHit = (src: any): any => {
  if (src == null) return null;
  if (typeof src !== 'object') {
    const m = normalizePricingMode(src);
    return m ? { mode: m, raw: src, via: 'value' } : null;
  }
  for (const f of ['pricing_mode', 'price_mode', 'mode', 'active_mode']) {
    const m = normalizePricingMode(src[f]);
    if (m) return { mode: m, raw: src[f], via: f };
  }
  return null;
};

const fixedSignalHit = (src: any): any => {
  if (!src || typeof src !== 'object') return null;
  const fixed = firstFinite(src.fixed_price, src.price_override, src.override_price);
  return fixed != null && fixed > 0
    ? { mode: PRICING_MODES.FIXED, raw: fixed, via: 'fixed_price' }
    : null;
};

const marketSignalHit = (src: any): any => {
  if (!src || typeof src !== 'object') return null;
  if (src.market_based === true || normStr(src.market_based) === 'true') {
    return { mode: PRICING_MODES.MARKET_BASED, raw: src.market_based, via: 'market_based' };
  }
  const retail = firstFinite(src.market_retail, src.retail_price, src.retail);
  return retail != null && retail > 0
    ? { mode: PRICING_MODES.MARKET_BASED, raw: retail, via: 'market_retail' }
    : null;
};

// tier_ref / tier / tier_name binding -> the bound chart row's family. A market
// row (pricing_mode market + finite market_retail) resolves 'market_based';
// any other bound row is the cost-plus family. A DANGLING ref resolves
// nothing — falls through rather than guessing.
const tierRefModeHit = (src: any, rows: any): any => {
  if (!src || typeof src !== 'object') return null;
  const ref = src.tier_ref ?? src.tier ?? src.tier_name;
  if (ref == null || !normStr(ref)) return null;
  const wanted = normStr(typeof ref === 'object' ? (ref as any).name ?? (ref as any).id : ref);
  const row = (Array.isArray(rows) ? rows : []).find(
    (r: any) => r && rowIsActive(r) && (normStr(r.name) === wanted || normStr(r.id) === wanted),
  );
  if (!row) return null;
  return {
    mode: marketKind(row) ? PRICING_MODES.MARKET_BASED : PRICING_MODES.COST_PLUS,
    raw: row,
    via: 'tier_ref',
  };
};

const descriptorModeHit = (src: any, rows: any): any =>
  explicitModeHit(src) || fixedSignalHit(src) || tierRefModeHit(src, rows) || marketSignalHit(src);

export function resolvePricingMode({ part = null, template = null, globalDefault = null, tierRules = null }: any = {}): any {
  const partHit = descriptorModeHit(part, tierRules);
  if (partHit) return { mode: partHit.mode, source: 'part', raw: partHit.raw, via: partHit.via };
  const tplHit = descriptorModeHit(template, tierRules);
  if (tplHit) return { mode: tplHit.mode, source: 'template', raw: tplHit.raw, via: tplHit.via };
  const gHit = descriptorModeHit(globalDefault, tierRules);
  if (gHit) return { mode: gHit.mode, source: 'global', raw: gHit.raw, via: gHit.via };
  return { mode: PRICING_MODES.COST_PLUS, source: 'default', raw: null, via: 'fallback' };
}
